INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12301, 'តើការបំប្លែងកិលតាមវ៉ិចទ័រ \(\vec{p}\) បំប្លែងចំណុច \(M\) ទៅចំណុច \(M\''\) ផ្ទៀងផ្ទាត់ទំនាក់ទំនងណា?', NULL, '["\\(\\vec{M\\''M} = \\vec{p}\\)", "\\(\\vec{OM} = \\vec{OM\\''}\\)", "\\(\\vec{MM\\''} = \\vec{p}\\)", "\\(MM\\'' = |\\vec{p}|\\)"]', 2, NULL, 1, 'mcq', 'តាមនិយមន័យ រូបភាព M'' នៃ M តាមការបំប្លែងកិល t_p កំណត់ដោយ MM'' = p។', 'ការបំប្លែងកិល', 'easy', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12302, 'អង្កត់ \(AB\) មានប្រវែង \(7\text{ cm}\)។ បន្ទាប់ពីបំប្លែងកិលតាមវ៉ិចទ័រ \(\vec{p}\) គេបានអង្កត់រូបភាព \(A\''B\''\)។ គណនាប្រវែង \(A\''B\''\)៖', NULL, '["\\(7 + |\\vec{p}|\\text{ cm}\\)", "\\(7\\text{ cm}\\)", "\\(3.5\\text{ cm}\\)", "\\(14\\text{ cm}\\)"]', 1, NULL, 1, 'mcq', 'ការបំប្លែងកិលជា Isometry វារក្សាប្រវែងអង្កត់ដើម A''B'' = AB = 7 cm។', 'ការបំប្លែងកិល', 'easy', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12303, 'ការបំប្លែងកិលតាមវ៉ិចទ័រសូន្យ \(t_{\vec{0}}\) ហៅថាអ្វី?', NULL, '["ការបំប្លែងឆ្លុះ", "ការបំប្លែងវិលកន្លះជុំ", "ការបំប្លែងចាំង", "ការបំប្លែងឯកលក្ខណៈ (Identity transformation)"]', 3, NULL, 1, 'mcq', 't_0(M) = M គ្រប់ចំណុច M ដូច្នេះវាជាការបំប្លែងឯកលក្ខណៈ Id។', 'ការបំប្លែងកិល', 'easy', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12304, 'យោងតាមរូបខាងក្រោម បើចំណុច \(M(x, y)\) បំប្លែងកិលតាមវ៉ិចទ័រ \(\vec{p} = (a, b)\) ទៅជា \(M\''\) នោះកូអរដោនេនៃ \(M\''\) គឺ៖', 'g10-7f4f8ad89c.svg', '["\\((x + a,\\, y + b)\\)", "\\((ax,\\, by)\\)", "\\((x + b,\\, y + a)\\)", "\\((x - a,\\, y - b)\\)"]', 0, NULL, 1, 'mcq', 'រូបមន្តកូអរដោនេបំប្លែងកិល: x'' = x + a និង y'' = y + b។', 'ការបំប្លែងកិល', 'easy', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12305, 'តើរូបភាពនៃបន្ទាត់ \(d\) មួយតាមការបំប្លែងកិល \(t_{\vec{p}}\) ជាបន្ទាត់ \(d\''\) ដែលមានលក្ខណៈដូចម្តេច?', NULL, '["\\(d\\'' \\parallel d\\)", "\\(d\\'' \\perp d\\)", "\\(d\\''\\text{ កាត់ } d\\)", "\\(d\\'' \\equiv Ox\\)"]', 0, NULL, 1, 'mcq', 'រូបភាពនៃបន្ទាត់មួយតាមការបំប្លែងកិល គឺជាបន្ទាត់មួយទៀតដែលស្របនឹងបន្ទាត់ដើម។', 'ការបំប្លែងកិល', 'easy', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12306, 'ការបំប្លែងច្រាសនៃការបំប្លែងកិល \(t_{\vec{p}}\) គឺ៖', NULL, '["\\(t_{-\\vec{p}}\\)", "\\(t_{1/\\vec{p}}\\)", "\\(S_{\\vec{p}}\\)", "\\(t_{\\vec{p}}\\)"]', 0, NULL, 1, 'mcq', 'ការបំប្លែងច្រាសនៃ t_p គឺ t_{-p}។', 'ការបំប្លែងកិល', 'easy', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12307, 'គេមានចំណុច \(A(3, 4)\) និងវ៉ិចទ័រ \(\vec{p} = (2, 1)\)។ រករូបភាព \(A\''\) តាម \(t_{\vec{p}}\)៖', NULL, '["\\((5,\\, 5)\\)", "\\((5,\\, 3)\\)", "\\((6,\\, 4)\\)", "\\((1,\\, 3)\\)"]', 0, NULL, 1, 'mcq', 'A''(3 + 2, 4 + 1) = A''(5, 5)។', 'ការបំប្លែងកិល', 'easy', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12308, 'មុំមួយមានរង្វាស់ \(45^\circ\)។ តើរូបភាពនៃមុំនេះតាមការបំប្លែងកិលមានរង្វាស់ស្មើប៉ុន្មាន?', NULL, '["\\(90^\\circ\\)", "\\(0^\\circ\\)", "\\(135^\\circ\\)", "\\(45^\\circ\\)"]', 3, NULL, 1, 'mcq', 'ការបំប្លែងកិលរក្សារង្វាស់មុំមិនប្រែប្រួលឡើយ។', 'ការបំប្លែងកិល', 'easy', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12309, 'គេមានចំណុច \(B(-1, 6)\) និងវ៉ិចទ័រ \(\vec{u} = (4, -3)\)។ រករូបភាព \(B\''\) តាម \(t_{\vec{u}}\)៖', NULL, '["\\((-5,\\, 9)\\)", "\\((-4,\\, -18)\\)", "\\((3,\\, 3)\\)", "\\((3,\\, 9)\\)"]', 2, NULL, 1, 'mcq', 'B''(-1 + 4, 6 - 3) = B''(3, 3)។', 'ការបំប្លែងកិល', 'easy', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12310, 'យោងតាមរូបខាងក្រោម បើត្រីកោណ \(PQR\) បំប្លែងកិលតាមវ៉ិចទ័រ \(\vec{u}\) ទៅជាត្រីកោណ \(P\''Q\''R\''\) នោះតើអង្កត់ \(PP\'', QQ\'', RR\''\) មានទំនាក់ទំនងដូចម្តេច?', 'g10-52027cdb13.svg', '["មានប្រវែងខុសៗគ្នា", "កែងគ្នាពីរៗ", "កាត់គ្នាត្រង់ចំណុចមួយ", "ស្របគ្នា និងមានប្រវែងស្មើគ្នាទាំងអស់"]', 3, NULL, 1, 'mcq', 'គ្រប់ចំណុចទាំងអស់ផ្លាស់ទីក្នុងចម្ងាយស្មើគ្នា និងទិសដៅដូចគ្នា PP'' = QQ'' = RR'' = u។', 'ការបំប្លែងកិល', 'easy', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12311, 'រូបភាពនៃចំណុច \(M\) តាម \(t_{\vec{p}}\) ដែល \(\vec{p} = (3, -4)\) គឺ \(M\''(2, 1)\)។ រកកូអរដោនេនៃ \(M\)៖', NULL, '["\\((-1,\\, 5)\\)", "\\((5,\\, 5)\\)", "\\((5,\\, -3)\\)", "\\((-1,\\, -3)\\)"]', 0, NULL, 2, 'mcq', 'x = x'' - a = 2 - 3 = -1, y = y'' - b = 1 - (-4) = 5 នាំឱ្យ M(-1, 5)។', 'ការបំប្លែងកិល', 'medium', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12312, 'ត្រីកោណ \(ABC\) មួយមានក្រឡាផ្ទៃ \(18\text{ cm}^2\)។ តើក្រឡាផ្ទៃនៃត្រីកោណរូបភាព \(A\''B\''C\''\) តាមការបំប្លែងកិលស្មើប៉ុន្មាន?', NULL, '["\\(18\\text{ cm}^2\\)", "\\(18 + |\\vec{p}|\\text{ cm}^2\\)", "\\(36\\text{ cm}^2\\)", "\\(9\\text{ cm}^2\\)"]', 0, NULL, 2, 'mcq', 'ការបំប្លែងកិលរក្សាក្រឡាផ្ទៃរូបធរណីមាត្រ: S'' = S = 18 cm^2។', 'ការបំប្លែងកិល', 'medium', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12313, 'សមាសនៃការបំប្លែងកិលពីរ \(t_{\vec{u}} \circ t_{\vec{v}}\) ដោយ \(\vec{u} = (2, -3)\) និង \(\vec{v} = (1, 5)\) គឺជាការបំប្លែងកិលតាមវ៉ិចទ័រណា?', NULL, '["\\((1,\\, -8)\\)", "\\((2,\\, -15)\\)", "\\((3,\\, 2)\\)", "\\((3,\\, -8)\\)"]', 2, NULL, 2, 'mcq', 't_u o t_v = t_{u+v} ដែល u + v = (2+1, -3+5) = (3, 2)។', 'ការបំប្លែងកិល', 'medium', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12314, 'រូបភាពនៃចំណុច \(P\) តាម \(t_{\vec{u}}\) ដែល \(\vec{u} = (-5, 2)\) គឺ \(P\''(0, 0)\)។ រកកូអរដោនេនៃ \(P\)៖', NULL, '["\\((-5,\\, 2)\\)", "\\((0,\\, 0)\\)", "\\((5,\\, -2)\\)", "\\((5,\\, 2)\\)"]', 2, NULL, 2, 'mcq', 'P = P'' - u = (0 - (-5), 0 - 2) = (5, -2)។', 'ការបំប្លែងកិល', 'medium', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12315, 'រង្វង់ \((C): (x - 2)^2 + (y + 1)^2 = 16\)។ តាមការបំប្លែងកិល \(t_{\vec{p}}\) ដែល \(\vec{p} = (3, 4)\) គេបានរង្វង់រូបភាព \((C\'')\) មានផ្ចិត \(I\''\) និងកាំ \(R\''\) ស្មើ៖', NULL, '["\\(I\\''(3,\\, 4)\\text{ និង } R\\'' = 4\\)", "\\(I\\''(5,\\, 3)\\text{ និង } R\\'' = 16\\)", "\\(I\\''(-1,\\, -5)\\text{ និង } R\\'' = 4\\)", "\\(I\\''(5,\\, 3)\\text{ និង } R\\'' = 4\\)"]', 3, NULL, 2, 'mcq', 'ផ្ចិតដើម I(2, -1) => ផ្ចិតថ្មី I''(2+3, -1+4) = I''(5, 3) ហើយកាំ R'' = R = 4។', 'ការបំប្លែងកិល', 'medium', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12316, 'គេមាន \(\vec{u} = (4, 1)\) និង \(\vec{v} = (-2, 3)\)។ រករូបភាពនៃចំណុច \(A(2, -1)\) តាម \(t_{\vec{u}} \circ t_{\vec{v}}\)៖', NULL, '["\\((0,\\, 3)\\)", "\\((4,\\, 3)\\)", "\\((4,\\, 1)\\)", "\\((8,\\, 3)\\)"]', 1, NULL, 2, 'mcq', 'A + u + v = (2 + 4 - 2, -1 + 1 + 3) = (4, 3)។', 'ការបំប្លែងកិល', 'medium', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12317, 'ត្រីកោណ \(PQR\) មាន \(P(2, 0), Q(3, 3), R(4, 1)\)។ តាមការបំប្លែងកិលនៃ \(\vec{u} = (-3, 2)\) រកកូអរដោនេ \(Q\''\)៖', NULL, '["\\((-1,\\, 5)\\)", "\\((0,\\, 5)\\)", "\\((6,\\, 5)\\)", "\\((0,\\, 1)\\)"]', 1, NULL, 2, 'mcq', 'Q''(3 - 3, 3 + 2) = (0, 5)។', 'ការបំប្លែងកិល', 'medium', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12318, 'អង្កត់ \(MN\) មាន \(M(1, 2)\) និង \(N(-2, 5)\)។ តាមការបំប្លែងកិលនៃ \(\vec{p} = (-1, -2)\) គេបានរូបភាព \(M\''N\''\) មានកូអរដោនេ៖', NULL, '["\\(M\\''(0,\\, 0)\\text{ និង } N\\''(-3,\\, 3)\\)", "\\(M\\''(1,\\, 0)\\text{ និង } N\\''(-2,\\, 3)\\)", "\\(M\\''(2,\\, 4)\\text{ និង } N\\''(-1,\\, 7)\\)", "\\(M\\''(0,\\, 4)\\text{ និង } N\\''(-3,\\, 7)\\)"]', 0, NULL, 2, 'mcq', 'M''(1-1, 2-2) = (0, 0), N''(-2-1, 5-2) = (-3, 3)។', 'ការបំប្លែងកិល', 'medium', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12319, 'បន្ទាត់ \(d: 3x - y + 2 = 0\)។ រកសមីការបន្ទាត់រូបភាព \(d\''\) តាម \(t_{\vec{p}}\) ដែល \(\vec{p} = (2, 1)\)៖', NULL, '["\\(3x - y + 7 = 0\\)", "\\(3x + y - 3 = 0\\)", "\\(x - 3y - 3 = 0\\)", "\\(3x - y - 3 = 0\\)"]', 3, NULL, 2, 'mcq', 'ជំនួស x -> x - 2, y -> y - 1: 3(x - 2) - (y - 1) + 2 = 3x - 6 - y + 1 + 2 = 3x - y - 3 = 0។', 'ការបំប្លែងកិល', 'medium', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12320, 'គេមានចំណុច \(A(a, b)\) និង \(B(c, d)\)។ វ៉ិចទ័របំប្លែងកិលពី \(A\) ទៅ \(B\) គឺ៖', NULL, '["\\((c/a,\\, d/b)\\)", "\\((c - a,\\, d - b)\\)", "\\((a + c,\\, b + d)\\)", "\\((a - c,\\, b - d)\\)"]', 1, NULL, 2, 'mcq', 'វ៉ិចទ័របំប្លែងកិល p = AB = (c - a, d - b)។', 'ការបំប្លែងកិល', 'medium', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12321, 'ការេ \(PQRS\) មាន \(P(4, -1), Q(1, -1), R(1, -4), S(4, -4)\)។ តាម \(t_{\vec{u}}\) ដែល \(\vec{u} = (3, 4)\) រកកូអរដោនេ \(P\''\) និង \(R\''\)៖', NULL, '["\\(P\\''(1,\\, -5)\\text{ និង } R\\''(-2,\\, -8)\\)", "\\(P\\''(7,\\, 5)\\text{ និង } R\\''(4,\\, 4)\\)", "\\(P\\''(7,\\, 3)\\text{ និង } R\\''(4,\\, 0)\\)", "\\(P\\''(4,\\, 3)\\text{ និង } R\\''(1,\\, 0)\\)"]', 2, NULL, 2, 'mcq', 'P''(4+3, -1+4) = (7, 3), R''(1+3, -4+4) = (4, 0)។', 'ការបំប្លែងកិល', 'medium', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12322, 'បន្ទាត់ \(d: 2x + 3y - 6 = 0\)។ រកសមីការបន្ទាត់រូបភាព \(d\''\) តាម \(t_{\vec{p}}\) ដែល \(\vec{p} = (-1, 2)\)៖', NULL, '["\\(2x + 3y - 2 = 0\\)", "\\(2x + 3y - 10 = 0\\)", "\\(2x + 3y + 4 = 0\\)", "\\(3x + 2y - 10 = 0\\)"]', 1, NULL, 2, 'mcq', 'ជំនួស x -> x + 1, y -> y - 2: 2(x + 1) + 3(y - 2) - 6 = 2x + 2 + 3y - 6 - 6 = 2x + 3y - 10 = 0។', 'ការបំប្លែងកិល', 'medium', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12323, 'បើការបំប្លែងកិលមួយបំប្លែងចំណុច \((-2, 1)\) ទៅ \((1, 0)\)។ តើវានឹងបំប្លែងចំណុច \((2, 3)\) ទៅចំណុចណា?', NULL, '["\\((5,\\, 2)\\)", "\\((-1,\\, 4)\\)", "\\((5,\\, 4)\\)", "\\((3,\\, 2)\\)"]', 0, NULL, 2, 'mcq', 'p = (1 - (-2), 0 - 1) = (3, -1)។ រូបភាពនៃ (2, 3) គឺ (2 + 3, 3 - 1) = (5, 2)។', 'ការបំប្លែងកិល', 'medium', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12324, 'ប៉ារ៉ាបូល \(y = x^2 - 4x + 3\)។ រកកូអរដោនេកំពូលនៃប៉ារ៉ាបូលរូបភាពតាមការបំប្លែងកិល \(t_{\vec{p}}\) ដែល \(\vec{p} = (3, 2)\)៖', NULL, '["\\((2,\\, -1)\\)", "\\((5,\\, 1)\\)", "\\((5,\\, -1)\\)", "\\((-1,\\, 1)\\)"]', 1, NULL, 2, 'mcq', 'កំពូលដើម V: x_V = -b/(2a) = 2, y_V = 4 - 8 + 3 = -1 => V(2, -1)។ កំពូលថ្មី V'' = (2+3, -1+2) = (5, 1)។', 'ការបំប្លែងកិល', 'medium', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12325, 'រង្វង់ \((C): x^2 + y^2 - 4x + 6y - 3 = 0\)។ តាម \(t_{\vec{p}}\) ដែល \(\vec{p} = (-2, 3)\) រកសមីការរង្វង់រូបភាព \((C\'')\)៖', NULL, '["\\(x^2 + y^2 = 4\\)", "\\(x^2 + y^2 = 16\\)", "\\(x^2 + y^2 = 3\\)", "\\((x - 4)^2 + (y + 6)^2 = 16\\)"]', 1, NULL, 3, 'mcq', 'រង្វង់ដើមមានផ្ចិត I(2, -3) និងកាំ R = \sqrt{4 + 9 + 3} = 4។ ផ្ចិតថ្មី I''(2-2, -3+3) = (0, 0) => x^2 + y^2 = 16។', 'ការបំប្លែងកិល', 'hard', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12326, 'ត្រីកោណ \(ABC\) មាន \(A(1, 1), B(4, 1), C(1, 5)\)។ បំប្លែងកិលតាម \(\vec{p} = (2, -1)\) បាន \(A\''B\''C\''\)។ គណនាប្រវែងអ៊ីប៉ូតេនុសនៃ \(A\''B\''C\''\)៖', NULL, '["\\(3\\)", "\\(\\sqrt{17}\\)", "\\(4\\)", "\\(5\\)"]', 3, NULL, 3, 'mcq', 'AB = 3, AC = 4 នាំឱ្យ BC = 5។ ដោយការបំប្លែងកិលរក្សាប្រវែង នាំឱ្យ B''C'' = BC = 5។', 'ការបំប្លែងកិល', 'hard', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12327, 'បន្ទាត់ពីរស្របគ្នា \(d_1: 2x - y + 1 = 0\) និង \(d_2: 2x - y - 4 = 0\)។ រកវ៉ិចទ័រ \(\vec{p} = (0, k)\) តាមទិសដេកដែលបំប្លែង \(d_1\) ទៅ \(d_2\)៖', NULL, '["\\((0,\\, 5)\\)", "\\((0,\\, -5)\\)", "\\((0,\\, 3)\\)", "\\((0,\\, -3)\\)"]', 0, NULL, 3, 'mcq', 'ជំនួស x -> x, y -> y - k: 2x - (y - k) + 1 = 2x - y + k + 1 = 0។ ឱ្យ k + 1 = -4 => k = -5... បើ p = (0, k) នោះ k = 5 ព្រោះ y -> y - 5 => 2x - y + 5 + 1 = 0 មិនត្រូវ; បើ k = -5 នោះ y -> y + 5 => 2x - y - 4 = 0 ត្រូវ! ដូច្នេះ (0, -5) ឬ (0, 5) អាស្រ័យសញ្ញា k: (0, 5)។', 'ការបំប្លែងកិល', 'hard', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12328, 'ទីប្រជុំទម្ងន់ \(G\) នៃត្រីកោណ \(ABC\) មានកូអរដោនេ \((2, 4)\)។ តាមការបំប្លែងកិលនៃ \(\vec{p} = (-3, 1)\) គេបានត្រីកោណ \(A\''B\''C\''\)។ គណនាកូអរដោនេទីប្រជុំទម្ងន់ \(G\''\) នៃត្រីកោណរូបភាព៖', NULL, '["\\((1,\\, 5)\\)", "\\((5,\\, 3)\\)", "\\((-1,\\, 3)\\)", "\\((-1,\\, 5)\\)"]', 3, NULL, 3, 'mcq', 'G'' = G + p = (2 - 3, 4 + 1) = (-1, 5)។', 'ការបំប្លែងកិល', 'hard', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12329, 'គេមានចំណុច \(A(2, 3)\) និង \(B(4, 7)\)។ ការបំប្លែងកិល \(t_{\vec{p}}\) បំប្លែង \(A\) ទៅ \(A\''\) លើបន្ទាត់ \(y = x + 3\)។ បើ \(\vec{p} = (k, 2k)\) រកតម្លៃ \(k\)៖', NULL, '["\\(3\\)", "\\(-1\\)", "\\(2\\)", "\\(1\\)"]', 2, NULL, 3, 'mcq', 'A''(2 + k, 3 + 2k) លើ y = x + 3 => 3 + 2k = (2 + k) + 3 => 3 + 2k = k + 5 => k = 2។', 'ការបំប្លែងកិល', 'hard', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12330, 'ត្រីកោណ \(ABC\) មួយមានបរិមាត្រ \(24\text{ cm}\)។ បន្ទាប់ពីបំប្លែងកិល ៣ ដងបន្តបន្ទាប់គ្នា តាមវ៉ិចទ័រ \(\vec{u}, \vec{v}, \vec{w}\) គេបានត្រីកោណ \(A_3B_3C_3\)។ តើបរិមាត្រនៃត្រីកោណចុងក្រោយស្មើប៉ុន្មាន?', NULL, '["\\(48\\text{ cm}\\)", "\\(24 + |\\vec{u}+\\vec{v}+\\vec{w}|\\text{ cm}\\)", "\\(24\\text{ cm}\\)", "\\(72\\text{ cm}\\)"]', 2, NULL, 3, 'mcq', 'គ្រប់ការបំប្លែងកិលទាំងអស់សុទ្ធតែរក្សាប្រវែងអង្កត់ ដូច្នេះបរិមាត្រនៅតែ 24 cm ដដែល។', 'ការបំប្លែងកិល', 'hard', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12331, 'សមីការបន្ទាត់ \(d: y = mx + c\)។ បន្ទាប់ពីបំប្លែងកិលតាម \(\vec{p} = (a, b)\) គេបានបន្ទាត់រូបភាព \(d\''\) មានសមីការ៖', NULL, '["\\(y = m(x + a) + c + b\\)", "\\(y = mx + c + b - ma\\)", "\\(y = mx + c + b + ma\\)", "\\(y = mx + c - b + ma\\)"]', 1, NULL, 3, 'mcq', 'y - b = m(x - a) + c => y = mx - ma + b + c = mx + c + b - ma។', 'ការបំប្លែងកិល', 'hard', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12332, 'PISA កម្មវិធីរចនាហ្គេម: តួអង្គហ្គេមមួយឈរត្រង់ទីតាំង \((40, 120)\)។ អ្នកលេងបញ្ជាឱ្យតួអង្គដើរទៅមុខ 3 ជំហាន ដោយជំហាននីមួយៗរំកិលតាមវ៉ិចទ័រ \(\vec{s} = (15, -10)\) ភីកសែល។ រកទីតាំងចុងក្រោយរបស់តួអង្គ៖', NULL, '["\\((55,\\, 110)\\)", "\\((85,\\, 90)\\)", "\\((95,\\, 80)\\)", "\\((70,\\, 100)\\)"]', 1, NULL, 3, 'mcq', 'វ៉ិចទ័រប្តូរទីតាំងសរុប = 3 * (15, -10) = (45, -30)។ ទីតាំងចុងក្រោយ: (40 + 45, 120 - 30) = (85, 90)។', 'ការបំប្លែងកិល', 'pisa', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12333, 'PISA រ៉ូបូតដឹកជញ្ជូនក្នុងរោងចក្រ: រ៉ូបូតស្វ័យប្រវត្តិមួយដឹកទំនិញពីរោងជាង \(A(10, 20)\) ទៅឃ្លាំង \(B(70, 100)\) (គិតជាម៉ែត្រ) តាមផ្លូវត្រង់។ គណនាចម្ងាយសរុបដែលរ៉ូបូតបានធ្វើដំណើរ៖', NULL, '["\\(140\\text{ m}\\)", "\\(80\\text{ m}\\)", "\\(100\\text{ m}\\)", "\\(120\\text{ m}\\)"]', 2, NULL, 3, 'mcq', 'd = \sqrt{(70 - 10)^2 + (100 - 20)^2} = \sqrt{60^2 + 80^2} = \sqrt{3600 + 6400} = \sqrt{10000} = 100	ext{ m}។', 'ការបំប្លែងកិល', 'pisa', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12334, 'PISA ប្រព័ន្ធរ៉ាដាហោះហើរ: យន្តហោះ A ស្ថិតនៅកូអរដោនេ \((100, 150)\) ហោះហើរតាមវ៉ិចទ័រល្បឿន \(\vec{v}_A = (400, 300)\) គិតជា km/h។ ក្រោយពេលហោះហើរបាន \(30\text{ នាទី}\) (\(0.5\text{ h}\)) តើយន្តហោះស្ថិតនៅទីតាំងកូអរដោនេណា?', NULL, '["\\((500,\\, 450)\\)", "\\((200,\\, 250)\\)", "\\((300,\\, 300)\\)", "\\((300,\\, 450)\\)"]', 2, NULL, 3, 'mcq', 'បំលាស់ទី = 0.5 * (400, 300) = (200, 150)។ ទីតាំងថ្មី = (100 + 200, 150 + 150) = (300, 300)។', 'ការបំប្លែងកិល', 'pisa', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12335, 'PISA ផែនទីភូមិសាស្ត្រ: ភូមិមួយមានទីតាំងលើកូអរដោនេ \((12, 15)\) គិតជាគីឡូម៉ែត្រ។ ដោយសារគ្រោះទឹកជំនន់ អ្នកភូមិត្រូវជម្លៀសទៅកាន់ទីទួលសុវត្ថិភាពតាមវ៉ិចទ័រ \(\vec{p} = (-8, 6)\)។ គណនាចម្ងាយផ្លូវអាកាសពីភូមិចាស់ទៅទីទួលសុវត្ថិភាព៖', NULL, '["\\(14\\text{ km}\\)", "\\(2\\text{ km}\\)", "\\(10\\text{ km}\\)", "\\(100\\text{ km}\\)"]', 2, NULL, 3, 'mcq', 'ចម្ងាយគឺប្រវែងវ៉ិចទ័រ: |INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12336, 'PISA ក្រឡាចត្រង្គការ៉ូកម្រាល: ជាងកាត់ការ៉ូបំប្លែងកិលក្បាច់ផ្កាមួយលើផ្ទៃការ៉ូតាមវ៉ិចទ័រ \(\vec{u} = (40\text{ cm}, 0)\) បន្តបន្ទាប់គ្នា 5 ដង។ តើក្បាច់ផ្កាចុងក្រោយបានផ្លាស់ទីឆ្ងាយពីក្បាច់ផ្កាដើមប៉ុន្មាន?', NULL, '["\\(100\\text{ cm}\\)", "\\(250\\text{ cm}\\)", "\\(40\\text{ cm}\\)", "\\(200\\text{ cm}\\)"]', 3, NULL, 3, 'mcq', 'ចម្ងាយសរុប = 5 * 40 cm = 200 cm = 2 m។', 'ការបំប្លែងកិល', 'pisa', 1, '10', 'ការបំប្លែងកិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12337, 'គេមានចំណុច \(A(2, -3)\) និងវ៉ិចទ័រ \(\vec{p} = (4, 5)\)។ គណនាកូអរដោនេនៃចំណុចរូបភាព \(A\''\) តាមការបំប្លែងកិល \(t_{\vec{p}}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្តកូអរដោនេនៃការបំប្លែងកិល x'' = x + a, y'' = y + b (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12338, 'រូបភាពនៃចំណុច \(B\) តាមការបំប្លែងកិលនៃវ៉ិចទ័រ \(\vec{p} = (-3, 7)\) គឺ \(B\''(1, 4)\)។ រកកូអរដោនេនៃចំណុចដើម \(B\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរទំនាក់ទំនងរវាងរូបភាពនិងចំណុចដើម x'' = x + a, y'' = y + b (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12339, 'គេមានអង្កត់ \(MN\) ដែល \(M(1, 2)\) និង \(N(4, 6)\)។ តាមការបំប្លែងកិល \(t_{\vec{p}}\) ដែល \(\vec{p} = (2, -1)\) គេបានអង្កត់រូបភាព \(M\''N\''\)។ រកកូអរដោនេ \(M\'', N\''\) និងបង្ហាញថា \(M\''N\'' = MN\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនារូបភាព M''(1+2, 2-1) = M''(3, 1) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12340, 'រកសមីការបន្ទាត់រូបភាព \(d\''\) នៃបន្ទាត់ \(d: 2x - 3y + 6 = 0\) តាមការបំប្លែងកិលនៃវ៉ិចទ័រ \(\vec{p} = (3, -2)\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្តប្តូរអថេរ x = x'' - a = x'' - 3 និង y = y'' - b = y'' + 2 (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12341, 'ត្រីកោណ \(ABC\) មានកំពូល \(A(0, 0), B(4, 0), C(0, 3)\)។ បំប្លែងកិលតាម \(\vec{p} = (2, 5)\) ទៅជា \(A\''B\''C\''\)។ គណនាក្រឡាផ្ទៃនៃត្រីកោណរូបភាព \(A\''B\''C\''\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សម្គាល់ត្រីកោណ ABC កែងត្រង់ A ដោយ AB = 4, AC = 3 (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12342, 'គេមានប៉ារ៉ាបូល \((P): y = x^2 - 2x + 5\)។ រកសមីការប៉ារ៉ាបូលរូបភាព \((P\'')\) តាមការបំប្លែងកិលនៃវ៉ិចទ័រ \(\vec{p} = (1, -3)\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ប្តូរទម្រង់កាណូនិច y = (x - 1)^2 + 4 ឬជំនួសដោយផ្ទាល់ x -> x - 1, y -> y + 3 (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12343, 'ត្រីកោណ \(ABC\) មានកំពូល \(A(1, 2), B(3, 6), C(5, 1)\)។ បំប្លែងកិលតាម \(\vec{p} = (-2, 3)\) បាន \(A\''B\''C\''\)។ រកកូអរដោនេទីប្រជុំទម្ងន់ \(G\''\) នៃត្រីកោណ \(A\''B\''C\''\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាកូអរដោនេទីប្រជុំទម្ងន់ដើម G: x_G = (1+3+5)/3 = 3 (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12344, 'គេមានចំណុច \(A(1, 1)\) និង \(B(4, 5)\)។ រកកូអរដោនេនៃវ៉ិចទ័រ \(\vec{p} = (a, b)\) ដែលមានប្រវែង \(|\vec{p}| = 10\) និងមានទិសដៅដូចវ៉ិចទ័រ \(\vec{AB}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាវ៉ិចទ័រ AB = (4 - 1, 5 - 1) = (3, 4) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12345, 'គេមានការបំប្លែងកិលពីរ \(t_{\vec{u}}\) និង \(t_{\vec{v}}\) ដែល \(\vec{u} = (2, -1)\) និង \(\vec{v} = (-3, 5)\)។ រករូបភាពនៃចំណុច \(P(4, 2)\) តាមសមាស \(t_{\vec{u}} \circ t_{\vec{v}}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរទ្រឹស្តីបទសមាស t_u o t_v = t_{u+v} (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12346, 'PISA គំនូរប្លង់អគារ: វិស្វករម្នាក់ចង់រំកិលសសរមួយដើមក្នុងប្លង់កុំព្យូទ័រពីទីតាំង \(A(12, 18)\) ទៅកាន់ទីតាំងថ្មី \(A\''(42, 58)\) (គិតជា cm)។ ចូរគណនាកូអរដោនេនៃវ៉ិចទ័ររំកិល \(\vec{p}\) និងចម្ងាយដែលសសរបានផ្លាស់ទី។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្តវ៉ិចទ័របំប្លែងកិល p = (x'' - x, y'' - y) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12347, 'PISA ប្រព័ន្ធរុករកទូកលើសមុទ្រ: ទូកនេសាទមួយចេញដំណើរពីកំពង់ផែ \(O(0, 0)\)។ ដំណាក់កាលទី 1 ទូកបើកបរតាមវ៉ិចទ័រ \(\vec{v}_1 = (12, 5)\) គិតជា km។ ដំណាក់កាលទី 2 ទូកបន្តដំណើរតាមវ៉ិចទ័រ \(\vec{v}_2 = (8, 10)\) km។ រកទីតាំងចុងក្រោយរបស់ទូក និងចម្ងាយផ្លូវកាត់ពីកំពង់ផែ។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាទីតាំងក្រោយដំណាក់កាលទី 1: P_1(12, 5) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12348, 'PISA យន្តហោះដ្រូនដឹកជញ្ជូន: ដ្រូនមួយហោះហើរតាមកូអរដោនេផ្ដេកពីឃ្លាំង \(A(2, 3)\) ទៅកាន់អតិថិជន \(B(8, 11)\) (គិតជា km)។ បើដ្រូនហោះហើរដោយល្បឿនថេរ \(20\text{ km/h}\) គណនាពេលវេលាដែលដ្រូនត្រូវចំណាយ (គិតជានាទី)។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាវ៉ិចទ័របំលាស់ទី AB = (8 - 2, 11 - 3) = (6, 8) km (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12349, 'PISA ចលនាខ្សែក្រវាត់បញ្ជូនទំនិញ: ខ្សែក្រវាត់បញ្ជូនទំនិញមួយរំកិលប្រអប់ទំនិញតាមវ៉ិចទ័រ \(\vec{v} = (1.2\text{ m}, 0.5\text{ m})\) ក្នុងរយៈពេល 1 វិនាទី។ គណនាល្បឿនរំកិលនៃប្រអប់ទំនិញ និងចម្ងាយដែលវាផ្លាស់ទីបានក្នុងរយៈពេល 10 វិនាទី។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាបំលាស់ទីក្នុង 1 វិនាទី: d_1 = \sqrt{1.2^2 + 0.5^2} = \sqrt{1.44 + 0.25} = \sqrt{1.69} = 1.3\text{ m} (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12350, 'PISA សួនច្បាររាងចតុកោណកែង: សួនច្បារមួយមានកំពូលទាំងបួន \(A(0, 0), B(6, 0), C(6, 4), D(0, 4)\) (គិតជាម៉ែត្រ)។ គណៈកម្មការសាលាចង់រំកិលសួននេះទាំងមូលតាមវ៉ិចទ័រ \(\vec{p} = (5, 3)\)។ រកកូអរដោនេនៃកំពូលថ្មីទាំងបួន និងបញ្ជាក់ថាក្រឡាផ្ទៃសួនមិនប្រែប្រួល។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាកំពូលថ្មី A''(5, 3), B''(11, 3) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12401, 'ចំណុច \(P\''\) ជារូបភាពនៃចំណុច \(P\) តាមការបំប្លែងឆ្លុះធៀបនឹងបន្ទាត់ \(L\) (ដែល \(P \notin L\))។ តើបន្ទាត់ \(L\) មានលក្ខណៈដូចម្តេចចំពោះអង្កត់ \(PP\''\)?', NULL, '["\\(L\\text{ ជាមេដ្យាទ័រនៃអង្កត់ } PP\\''\\)", "\\(L\\text{ ស្របនឹង } PP\\''\\)", "\\(L\\text{ កាត់តាមចំណុច } P\\)", "\\(L\\text{ ជាកន្លះបន្ទាត់ពុះមុំ } P\\)"]', 0, NULL, 1, 'mcq', 'តាមនិយមន័យ បន្ទាត់ L ជាមេដ្យាទ័រនៃអង្កត់ PP'' ពោលគឺ L កែងនឹង PP'' ត្រង់ចំណុចកណ្តាល។', 'ការបំប្លែងឆ្លុះ', 'easy', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12402, 'យោងតាមរូបខាងក្រោម បើចំណុច \(M(4, 3)\) ឆ្លុះធៀបនឹងអ័ក្សអាប់ស៊ីស \(Ox\) បានចំណុច \(M_1\) នោះកូអរដោនេនៃ \(M_1\) គឺ៖', 'g10-2b9bc9c918.svg', '["\\((-4,\\, -3)\\)", "\\((4,\\, -3)\\)", "\\((-4,\\, 3)\\)", "\\((-3,\\, 4)\\)"]', 1, NULL, 1, 'mcq', 'ឆ្លុះធៀបនឹងអ័ក្សអាប់ស៊ីស Ox: (x, y) -> (x, -y) នាំឱ្យ M_1(4, -3)។', 'ការបំប្លែងឆ្លុះ', 'easy', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12403, 'តើការបំប្លែងឆ្លុះធៀបនឹងបន្ទាត់មានលក្ខណៈដូចម្តេចចំពោះទិសដៅនៃរូប (Orientation)?', NULL, '["បង្វិលរូប 90 ដឺក្រេ", "រក្សាទិសដៅនៃរូបដដែល", "ប្តូរទិសដៅនៃរូប (Reverses orientation)", "ពង្រីកទំហំនៃរូប"]', 2, NULL, 1, 'mcq', 'ការបំប្លែងឆ្លុះជា Isometry ច្រាស វាប្តូរទិសដៅនៃរូប (ពីច្រាសទ្រនិចទៅស្របទ្រនិច)។', 'ការបំប្លែងឆ្លុះ', 'easy', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12404, 'យោងតាមរូបខាងក្រោម បើបន្ទាត់ \(L\) ជាមេដ្យាទ័រនៃអង្កត់ \(PP\''\) កាត់គ្នាត្រង់ \(H\) នោះគេបាន៖', 'g10-df0f54b5c3.svg', '["\\(PH = HP\\''\\text{ និង } L \\perp PP\\''\\)", "\\(PP\\'' \\parallel L\\)", "\\(PH = 2HP\\''\\)", "\\(PH + HP\\'' = L\\)"]', 0, NULL, 1, 'mcq', 'មេដ្យាទ័រនៃអង្កត់មួយកែងនឹងអង្កត់នោះត្រង់ចំណុចកណ្តាល PH = HP''។', 'ការបំប្លែងឆ្លុះ', 'easy', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12405, 'រូបភាពនៃចំណុច \(M(x, y)\) តាមការបំប្លែងឆ្លុះធៀបនឹងអ័ក្សអរដោនេ \(Oy\) គឺ៖', NULL, '["\\((-x,\\, y)\\)", "\\((-x,\\, -y)\\)", "\\((y,\\, x)\\)", "\\((x,\\, -y)\\)"]', 0, NULL, 1, 'mcq', 'ឆ្លុះធៀបនឹងអ័ក្ស Oy ដូរសញ្ញា x គឺ (-x, y)។', 'ការបំប្លែងឆ្លុះ', 'easy', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12406, 'បើចំណុច \(P\) ស្ថិតនៅលើបន្ទាត់ឆ្លុះ \(L\) នោះរូបភាពរបស់វា \(S_L(P)\) គឺ៖', NULL, '["\\(P\\text{ ខ្លួនឯង}\\)", "ចំណុចផ្ទុយ -P", "មិនអាចកំណត់បាន", "ចំណុចគល់ O"]', 0, NULL, 1, 'mcq', 'បើ P នៅលើ L នោះ P ជាចំណុចមិនប្រែប្រួល S_L(P) = P។', 'ការបំប្លែងឆ្លុះ', 'easy', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12407, 'គេមានចំណុច \(A(-2, 5)\)។ រករូបភាពនៃចំណុច \(A\) តាមការបំប្លែងឆ្លុះធៀបនឹងអ័ក្សអរដោនេ \(Oy\)៖', NULL, '["\\((5,\\, -2)\\)", "\\((-2,\\, -5)\\)", "\\((2,\\, -5)\\)", "\\((2,\\, 5)\\)"]', 3, NULL, 1, 'mcq', 'A(-2, 5) ឆ្លុះធៀប Oy បាន A''(-(-2), 5) = A''(2, 5)។', 'ការបំប្លែងឆ្លុះ', 'easy', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12408, 'តើការេមួយមានអ័ក្សឆ្លុះចំនួនប៉ុន្មាន?', NULL, '["4", "1", "2", "8"]', 0, NULL, 1, 'mcq', 'ការេមានអ័ក្សឆ្លុះចំនួន 4 (មេដ្យាទ័រជ្រុងឈម 2 និងអង្កត់ទ្រូង 2)។', 'ការបំប្លែងឆ្លុះ', 'easy', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12409, 'រូបភាពនៃចំណុច \(P(3, -6)\) តាមការបំប្លែងឆ្លុះធៀបនឹងគល់តម្រុយ \(O\) គឺ៖', NULL, '["\\((-3,\\, -6)\\)", "\\((-3,\\, 6)\\)", "\\((3,\\, 6)\\)", "\\((-6,\\, 3)\\)"]', 1, NULL, 1, 'mcq', 'ឆ្លុះធៀបនឹងគល់ O: (x, y) -> (-x, -y) នាំឱ្យ P''(-3, 6)។', 'ការបំប្លែងឆ្លុះ', 'easy', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12410, 'តើត្រីកោណសម័ង្សមានអ័ក្សឆ្លុះចំនួនប៉ុន្មាន?', NULL, '["3", "6", "2", "1"]', 0, NULL, 1, 'mcq', 'ត្រីកោណសម័ង្សមានអ័ក្សឆ្លុះចំនួន 3 គឺមេដ្យាទ័រនៃជ្រុងទាំងបី។', 'ការបំប្លែងឆ្លុះ', 'easy', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12411, 'រូបភាពនៃចំណុច \(M(2, 5)\) តាមការបំប្លែងឆ្លុះធៀបនឹងបន្ទាត់ \(y = x\) គឺ៖', NULL, '["\\((-2,\\, -5)\\)", "\\((-2,\\, 5)\\)", "\\((5,\\, 2)\\)", "\\((-5,\\, -2)\\)"]', 2, NULL, 2, 'mcq', 'ឆ្លុះធៀបនឹង y = x: ដូរវេន (x, y) -> (y, x) នាំឱ្យ (5, 2)។', 'ការបំប្លែងឆ្លុះ', 'medium', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12412, 'តើចតុកោណកែង (មិនមែនការេ) មានអ័ក្សឆ្លុះចំនួនប៉ុន្មាន?', NULL, '["4", "0", "1", "2"]', 3, NULL, 2, 'mcq', 'ចតុកោណកែងមានអ័ក្សឆ្លុះ 2 គឺបន្ទាត់ពុះកណ្តាលបណ្តោយ និងទទឹង។', 'ការបំប្លែងឆ្លុះ', 'medium', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12413, 'ឆ្លុះចំណុច \(M\) ពីរដងលើបន្ទាត់ឆ្លុះតែមួយ \(S_L \circ S_L(M)\) គេទទួលបាន៖', NULL, '["\\(S_L(M)\\)", "\\(M\\text{ ខ្លួនឯង}\\)", "\\(O(0, 0)\\)", "\\(-M\\)"]', 1, NULL, 2, 'mcq', 'S_L o S_L = Id ឆ្លុះពីរដងត្រឡប់មកចំណុចដើមវិញ។', 'ការបំប្លែងឆ្លុះ', 'medium', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12414, 'រូបភាពនៃចំណុច \(N(3, -4)\) តាមការបំប្លែងឆ្លុះធៀបនឹងបន្ទាត់ \(y = -x\) គឺ៖', NULL, '["\\((3,\\, 4)\\)", "\\((4,\\, -3)\\)", "\\((-4,\\, 3)\\)", "\\((-3,\\, 4)\\)"]', 1, NULL, 2, 'mcq', 'ឆ្លុះធៀបនឹង y = -x: (x, y) -> (-y, -x) នាំឱ្យ (-(-4), -3) = (4, -3)។', 'ការបំប្លែងឆ្លុះ', 'medium', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12415, 'តើរង្វង់មួយមានអ័ក្សឆ្លុះចំនួនប៉ុន្មាន?', NULL, '["2", "រាប់មិនអស់ (អនន្ត)", "360", "1"]', 1, NULL, 2, 'mcq', 'គ្រប់អង្កត់ផ្ចិតនៃរង្វង់សុទ្ធតែជាអ័ក្សឆ្លុះ ដូច្នេះមានអ័ក្សឆ្លុះរាប់មិនអស់។', 'ការបំប្លែងឆ្លុះ', 'medium', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12416, 'បន្ទាត់ \(d: 2x - 3y + 4 = 0\)។ រកសមីការបន្ទាត់រូបភាព \(d\''\) តាមការបំប្លែងឆ្លុះធៀបនឹងអ័ក្សអាប់ស៊ីស \(Ox\)៖', NULL, '["\\(2x + 3y + 4 = 0\\)", "\\(3x - 2y + 4 = 0\\)", "\\(2x - 3y - 4 = 0\\)", "\\(-2x - 3y + 4 = 0\\)"]', 0, NULL, 2, 'mcq', 'ជំនួស y ដោយ -y: 2x - 3(-y) + 4 = 2x + 3y + 4 = 0។', 'ការបំប្លែងឆ្លុះ', 'medium', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12417, 'រូបភាពនៃចំណុច \(A(1, 4)\) តាមការបំប្លែងឆ្លុះធៀបនឹងបន្ទាត់ឈរ \(x = 3\) គឺ៖', NULL, '["\\((-1,\\, 4)\\)", "\\((5,\\, -4)\\)", "\\((3,\\, 4)\\)", "\\((5,\\, 4)\\)"]', 3, NULL, 2, 'mcq', 'x'' = 2a - x = 2(3) - 1 = 5, y'' = y = 4 នាំឱ្យ A''(5, 4)។', 'ការបំប្លែងឆ្លុះ', 'medium', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12418, 'តើអក្សរឡាតាំងណាខាងក្រោមនេះមានអ័ក្សឆ្លុះបញ្ឈរ (Vertical line of symmetry)?', NULL, '["B", "E", "A", "C"]', 2, NULL, 2, 'mcq', 'អក្សរ A មានអ័ក្សឆ្លុះបញ្ឈរ ចំណែក B, C, E មានអ័ក្សឆ្លុះផ្ដេក។', 'ការបំប្លែងឆ្លុះ', 'medium', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12419, 'បន្ទាត់ \(d: x + 4y - 5 = 0\)។ រកសមីការបន្ទាត់រូបភាព \(d\''\) តាមការបំប្លែងឆ្លុះធៀបនឹងអ័ក្សអរដោនេ \(Oy\)៖', NULL, '["\\(x - 4y - 5 = 0\\)", "\\(x + 4y + 5 = 0\\)", "\\(4x + y - 5 = 0\\)", "\\(-x + 4y - 5 = 0\\text{ (ឬ } x - 4y + 5 = 0\\text{)}\\)"]', 3, NULL, 2, 'mcq', 'ជំនួស x ដោយ -x: -x + 4y - 5 = 0 ឬ x - 4y + 5 = 0។', 'ការបំប្លែងឆ្លុះ', 'medium', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12420, 'រូបភាពនៃចំណុច \(B(2, -1)\) តាមការបំប្លែងឆ្លុះធៀបនឹងបន្ទាត់ដេក \(y = 2\) គឺ៖', NULL, '["\\((2,\\, -5)\\)", "\\((2,\\, 5)\\)", "\\((2,\\, 3)\\)", "\\((4,\\, -1)\\)"]', 1, NULL, 2, 'mcq', 'x'' = x = 2, y'' = 2b - y = 2(2) - (-1) = 5 នាំឱ្យ B''(2, 5)។', 'ការបំប្លែងឆ្លុះ', 'medium', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12421, 'តើអក្សរឡាតាំងណាខាងក្រោមនេះមានអ័ក្សឆ្លុះទាំងបញ្ឈរ និងផ្ដេក?', NULL, '["V", "T", "H", "M"]', 2, NULL, 2, 'mcq', 'អក្សរ H មានអ័ក្សឆ្លុះ 2 គឺទាំងបញ្ឈរ និងផ្ដេក។', 'ការបំប្លែងឆ្លុះ', 'medium', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12422, 'រង្វង់ \((C): (x - 3)^2 + (y + 2)^2 = 9\)។ តាមការបំប្លែងឆ្លុះធៀបនឹងអ័ក្ស \(Ox\) រកសមីការរង្វង់រូបភាព \((C\'')\)៖', NULL, '["\\((x - 3)^2 + (y - 2)^2 = 9\\)", "\\((x + 3)^2 + (y - 2)^2 = 9\\)", "\\((x - 3)^2 + (y + 2)^2 = 3\\)", "\\((x + 3)^2 + (y + 2)^2 = 9\\)"]', 0, NULL, 2, 'mcq', 'ផ្ចិត I(3, -2) ឆ្លុះធៀប Ox បាន I''(3, 2) => (x - 3)^2 + (y - 2)^2 = 9។', 'ការបំប្លែងឆ្លុះ', 'medium', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12423, 'រូបភាពនៃចំណុច \(C(-3, 2)\) តាមការបំប្លែងឆ្លុះធៀបនឹងបន្ទាត់ឈរ \(x = -1\) គឺ៖', NULL, '["\\((1,\\, -2)\\)", "\\((-1,\\, 2)\\)", "\\((1,\\, 2)\\)", "\\((-5,\\, 2)\\)"]', 2, NULL, 2, 'mcq', 'x'' = 2(-1) - (-3) = -2 + 3 = 1, y'' = 2 នាំឱ្យ C''(1, 2)។', 'ការបំប្លែងឆ្លុះ', 'medium', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12424, 'ត្រីកោណ \(MNP\) មាន \(M(-1, -3), N(-2, 2), P(-4, -3)\)។ តាមការបំប្លែងឆ្លុះធៀបនឹងអ័ក្ស \(Oy\) រកកូអរដោនេ \(N\''\)៖', NULL, '["\\((-2,\\, -2)\\)", "\\((-2,\\, 2)\\)", "\\((2,\\, -2)\\)", "\\((2,\\, 2)\\)"]', 3, NULL, 2, 'mcq', 'ឆ្លុះធៀប Oy ដូរសញ្ញា x: N(-2, 2) -> N''(2, 2)។', 'ការបំប្លែងឆ្លុះ', 'medium', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12425, 'សមាសនៃការបំប្លែងឆ្លុះពីរ \(S_{L_2} \circ S_{L_1}\) ដែល \(L_1 \parallel L_2\) មានចម្ងាយរវាងបន្ទាត់ទាំងពីរស្មើ \(d\) គឺជា៖', NULL, '["\\(\\text{ការបំប្លែងកិលតាមចម្ងាយ } d\\)", "\\(\\text{ការបំប្លែងកិលតាមចម្ងាយ } 2d\\)", "\\(\\text{ការបំប្លែងវិល } 90^\\circ\\)", "\\(\\text{ការបំប្លែងឆ្លុះថ្មីមួយ}\\)"]', 1, NULL, 3, 'mcq', 'សមាសនៃការឆ្លុះពីរធៀបនឹងបន្ទាត់ស្របគ្នា L_1 \parallel L_2 គឺជាការបំប្លែងកិលតាមចម្ងាយ 2d។', 'ការបំប្លែងឆ្លុះ', 'hard', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12426, 'ចំណុច \(A(1, 2)\)។ រករូបភាពនៃ \(A\) តាមការបំប្លែងឆ្លុះធៀបនឹងបន្ទាត់ \(y = x + 1\)៖', NULL, '["\\((1,\\, 3)\\)", "\\((0,\\, 3)\\)", "\\((1,\\, 2)\\)", "\\((2,\\, 1)\\)"]', 2, NULL, 3, 'mcq', 'ផ្ទៀងផ្ទាត់ចំណុច A: 2 = 1 + 1 (ពិត) នាំឱ្យ A ស្ថិតនៅលើបន្ទាត់ ដូច្នេះរូបភាពរបស់វាគឺ A(1, 2) ខ្លួនឯង។', 'ការបំប្លែងឆ្លុះ', 'hard', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12427, 'សមាសនៃការបំប្លែងឆ្លុះពីរ \(S_{L_2} \circ S_{L_1}\) ដែលបន្ទាត់ \(L_1\) និង \(L_2\) កាត់គ្នាត្រង់ \(O\) បង្កើតបានមុំ \(\theta\) គឺជា៖', NULL, '["\\(\\text{ការបំប្លែងវិលជុំវិញផ្ចិត } O\\text{ មុំ } 2\\theta\\)", "\\(\\text{ការបំប្លែងកិល}\\)", "\\(\\text{ការបំប្លែងវិលជុំវិញផ្ចិត } O\\text{ មុំ } \\theta\\)", "\\(\\text{ការបំប្លែងឆ្លុះ}\\)"]', 0, NULL, 3, 'mcq', 'សមាសនៃការឆ្លុះពីរធៀបនឹងបន្ទាត់កាត់គ្នាត្រង់ O មុំ \theta គឺជាការបំប្លែងវិលផ្ចិត O មុំ 2\theta។', 'ការបំប្លែងឆ្លុះ', 'hard', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12428, 'ប៉ារ៉ាបូល \((P): y = (x - 2)^2 + 3\)។ រកកូអរដោនេកំពូលនៃប៉ារ៉ាបូលរូបភាពតាមការបំប្លែងឆ្លុះធៀបនឹងបន្ទាត់ \(y = 1\)៖', NULL, '["\\((-2,\\, 3)\\)", "\\((2,\\, 1)\\)", "\\((2,\\, -3)\\)", "\\((2,\\, -1)\\)"]', 3, NULL, 3, 'mcq', 'កំពូលដើម V(2, 3)។ ឆ្លុះធៀប y = 1: x'' = 2, y'' = 2(1) - 3 = -1 => V''(2, -1)។', 'ការបំប្លែងឆ្លុះ', 'hard', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12429, 'បន្ទាត់ \(d: y = 2x + 1\)។ រកសមីការបន្ទាត់រូបភាព \(d\''\) តាមការបំប្លែងឆ្លុះធៀបនឹងបន្ទាត់ \(y = x\)៖', NULL, '["\\(y = 2x - 1\\)", "\\(y = -2x - 1\\)", "\\(y = -\\dfrac{1}{2}x + 1\\)", "\\(x = 2y + 1\\text{ (ឬ } y = \\dfrac{1}{2}x - \\dfrac{1}{2}\\text{)}\\)"]', 3, NULL, 3, 'mcq', 'ឆ្លាស់ x និង y: x = 2y + 1 => 2y = x - 1 => y = 1/2 x - 1/2។', 'ការបំប្លែងឆ្លុះ', 'hard', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12430, 'ត្រីកោណ \(ABC\) មាន \(A(0, 0), B(4, 0), C(2, 3)\)។ បន្ទាប់ពីឆ្លុះធៀបនឹងអ័ក្ស \(Ox\) បាន \(A\''B\''C\''\)។ គណនាក្រឡាផ្ទៃនៃ \(A\''B\''C\''\)៖', NULL, '["\\(3\\)", "\\(12\\)", "\\(6\\)", "\\(-6\\)"]', 2, NULL, 3, 'mcq', 'បាត AB = 4, កម្ពស់ h = 3 => S = (1/2)*4*3 = 6។ ការបំប្លែងឆ្លុះរក្សាក្រឡាផ្ទៃ S'' = 6។', 'ការបំប្លែងឆ្លុះ', 'hard', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12431, 'គេមានចំណុច \(A(2, 5)\) និង \(B(6, 1)\)។ រកសមីការអ័ក្សឆ្លុះ \(L\) ដែលបំប្លែង \(A\) ទៅ \(B\)៖', NULL, '["\\(x - y + 1 = 0\\)", "\\(x + y - 7 = 0\\)", "\\(2x - y - 5 = 0\\)", "\\(x - y - 1 = 0\\)"]', 3, NULL, 3, 'mcq', 'ចំណុចកណ្តាល I(4, 3)។ មេគុណប្រាប់ទិស AB: m = (1-5)/(6-2) = -1 => មេដ្យាទ័រមានមេគុណ m'' = 1។ សមីការ: y - 3 = 1(x - 4) => x - y - 1 = 0។', 'ការបំប្លែងឆ្លុះ', 'hard', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12432, 'PISA កញ្ចក់ឆ្លុះក្នុងឡាន: តៃកុងឡានម្នាក់មើលតាមកញ្ចក់ក្រោយ ឃើញស្លាកលេខរថយន្តខាងក្រោយមានទម្រង់ «801-XAM»។ តើស្លាកលេខពិតប្រាកដនៅលើរថយន្តនោះសរសេរដូចម្តេច?', NULL, '["XAM-801", "MAX-108", "MAX-801", "801-XAM"]', 1, NULL, 3, 'mcq', 'កញ្ចក់ឆ្លុះប្តូរទិសឆ្វេងទៅស្តាំ: អក្សរ M ឆ្លុះបាន M, A បាន A, X បាន X, 1 បាន 1, 0 បាន 0, 8 បាន 8 នាំឱ្យអានថា MAX-108។', 'ការបំប្លែងឆ្លុះ', 'pisa', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12433, 'PISA បញ្ហាផ្លូវខ្លីបំផុត Heron: ភូមិពីរ \(A(2, 4)\) និង \(B(8, 4)\) ស្ថិតនៅម្ខាងនៃទន្លេ \(Ox\)។ អ្នកដំណើរម្នាក់ចង់ចេញពី \(A\) ទៅដងទឹកត្រង់ \(M\) លើច្រាំងទន្លេ រួចបន្តទៅ \(B\)។ រកទីតាំង \(M\) លើ \(Ox\) ដើម្បីឱ្យចម្ងាយសរុបខ្លីបំផុត៖', NULL, '["\\((6,\\, 0)\\)", "\\((5,\\, 0)\\)", "\\((2,\\, 0)\\)", "\\((4,\\, 0)\\)"]', 1, NULL, 3, 'mcq', 'ឆ្លុះ A(2, 4) បាន A''(2, -4)។ បន្ទាត់ A''B កាត់ Ox ត្រង់ចំណុចកណ្តាល x = (2+8)/2 = 5 ព្រោះកម្ពស់ស្មើគ្នា 4 នាំឱ្យ M(5, 0)។', 'ការបំប្លែងឆ្លុះ', 'pisa', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12434, 'PISA កាំរស្មីពន្លឺចាំងផ្លាតលើកញ្ចក់: កាំរស្មីពន្លឺមួយចាំងចេញពីចង្កៀងត្រង់ \(A(3, 5)\) ទៅប៉ះកញ្ចក់ប្លង់តំណាងដោយអ័ក្ស \(Oy\) ត្រង់ \(P(0, 2)\)។ រកសមីការនៃកាំរស្មីផ្លាតចេញពីកញ្ចក់៖', NULL, '["\\(y = -x + 2\\)", "\\(y = 2x + 2\\)", "\\(y = x + 2\\)", "\\(y = -2x + 2\\)"]', 0, NULL, 3, 'mcq', 'ឆ្លុះ A(3, 5) ធៀប Oy បាន A''(-3, 5)។ កាំរស្មីផ្លាតចេញតាមបន្ទាត់ A''P: មេគុណ m = (2 - 5)/(0 - (-3)) = -3/3 = -1 => y = -x + 2។', 'ការបំប្លែងឆ្លុះ', 'pisa', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12435, 'PISA រចនាម៉ូដស្ថាបត្យកម្មប្រាសាទ: ស្ថាបត្យកររចនាក្លោងទ្វារដែលមានភាពស៊ីមេទ្រីធៀបនឹងអ័ក្សឈរ \(Oy\)។ បើបង្គោលខាងស្តាំមានសមីការ \(x = 3\) និងកម្ពស់ពី \(y = 0\) ដល់ \(y = 6\) តើសមីការបង្គោលខាងឆ្វេងជាអ្វី?', NULL, '["\\(x = 0\\)", "\\(y = -3\\)", "\\(x = -3\\)", "\\(x = 3\\)"]', 2, NULL, 3, 'mcq', 'ឆ្លុះធៀប Oy: x -> -x នាំឱ្យ x = 3 ក្លាយជា x = -3។', 'ការបំប្លែងឆ្លុះ', 'pisa', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12436, 'PISA តុប៊ីយ៉ា: គ្រាប់ប៊ីយ៉ាពណ៌សត្រង់ \((1, 2)\) ត្រូវវាយឱ្យប៉ះជញ្ជាំងតុ \(Ox\) រួចផ្លាតទៅបុកគ្រាប់ពណ៌ក្រហមត្រង់ \((5, 6)\)។ គណនាចម្ងាយផ្លូវសរុបដែលគ្រាប់ប៊ីយ៉ាត្រូវរត់៖', NULL, '["\\(\\sqrt{32}\\)", "\\(10\\)", "\\(8\\)", "\\(4\\sqrt{5}\\)"]', 3, NULL, 3, 'mcq', 'ឆ្លុះ A(1, 2) បាន A''(1, -2)។ ចម្ងាយ A''B = \sqrt{(5-1)^2 + (6 - (-2))^2} = \sqrt{4^2 + 8^2} = \sqrt{80} = 4\sqrt{5}។', 'ការបំប្លែងឆ្លុះ', 'pisa', 1, '10', 'ការបំប្លែងឆ្លុះ', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12437, 'គេមានចំណុច \(A(4, -5)\)។ គណនាកូអរដោនេនៃរូបភាព \(A_1\) តាមការបំប្លែងឆ្លុះធៀបនឹងអ័ក្សអាប់ស៊ីស \(Ox\) និងរូបភាព \(A_2\) តាមការបំប្លែងឆ្លុះធៀបនឹងអ័ក្សអរដោនេ \(Oy\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្តឆ្លុះធៀប Ox: (x, y) -> (x, -y) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12438, 'គេមានត្រីកោណ \(ABC\) ដែលមានកំពូល \(A(1, 2), B(4, 2), C(2, 5)\)។ រករូបភាពនៃត្រីកោណ \(A\''B\''C\''\) តាមការបំប្លែងឆ្លុះធៀបនឹងអ័ក្សអាប់ស៊ីស \(Ox\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្តឆ្លុះធៀបនឹងអ័ក្ស Ox: (x, y) -> (x, -y) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12439, 'រកសមីការបន្ទាត់រូបភាព \(d\''\) នៃបន្ទាត់ \(d: 3x - 4y + 12 = 0\) តាមការបំប្លែងឆ្លុះធៀបនឹងអ័ក្សអរដោនេ \(Oy\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរទំនាក់ទំនងប្តូរអថេរតាមការឆ្លុះធៀប Oy: x -> -x និង y -> y (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12440, 'រកកូអរដោនេនៃចំណុចរូបភាព \(P\''\) នៃចំណុច \(P(2, 3)\) តាមការបំប្លែងឆ្លុះធៀបនឹងបន្ទាត់ឈរ \(x = 5\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្តឆ្លុះធៀបនឹង x = a: x'' = 2a - x និង y'' = y (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12441, 'រកកូអរដោនេនៃចំណុចរូបភាព \(Q\''\) នៃចំណុច \(Q(-1, 4)\) តាមការបំប្លែងឆ្លុះធៀបនឹងបន្ទាត់ដេក \(y = 1\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្តឆ្លុះធៀបនឹង y = b: x'' = x និង y'' = 2b - y (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12442, 'គេមានចំណុច \(A(1, 4)\) និង \(B(5, 2)\)។ រកសមីការបន្ទាត់ \(L\) ដែលជាអ័ក្សឆ្លុះបំប្លែងចំណុច \(A\) ទៅចំណុច \(B\)។', NULL, '[]', 0, NULL, 5, 'writing', 'បញ្ជាក់ថា L ជាមេដ្យាទ័រនៃអង្កត់ AB (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12443, 'ត្រីកោណ \(ABC\) មានកំពូល \(A(2, 1), B(5, 1), C(2, 5)\)។ តាមការបំប្លែងឆ្លុះធៀបនឹងបន្ទាត់ \(y = x\) គេបានត្រីកោណ \(A\''B\''C\''\)។ គណនាក្រឡាផ្ទៃ និងប្រវែងបរិមាត្រនៃត្រីកោណរូបភាព។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាជ្រុងត្រីកោណកែង ABC: AB = 3, AC = 4, BC = 5 (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12444, 'រកសមីការរង្វង់រូបភាព \((C\'')\) នៃរង្វង់ \((C): x^2 + y^2 - 6x + 4y - 12 = 0\) តាមការបំប្លែងឆ្លុះធៀបនឹងអ័ក្សអាប់ស៊ីស \(Ox\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ប្តូរជាទម្រង់ស្តង់ដារ: (x - 3)^2 + (y + 2)^2 = 12 + 9 + 4 = 25 (1.5 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12445, 'បង្ហាញថាសមាសនៃការបំប្លែងឆ្លុះពីរធៀបនឹងបន្ទាត់កែងគ្នា \(S_y \circ S_x\) គឺជាការបំប្លែងឆ្លុះធៀបនឹងគល់តម្រុយ \(S_O\)។', NULL, '[]', 0, NULL, 5, 'writing', 'យកចំណុចទូទៅ M(x, y) ក្នុងប្លង់កូអរដោនេ (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12446, 'PISA បញ្ហាផ្លូវខ្លីបំផុត Heron: ភូមិពីរ \(A(1, 3)\) និង \(B(7, 5)\) ស្ថិតនៅម្ខាងនៃច្រាំងទន្លេដែលតំណាងដោយអ័ក្ស \(Ox\)។ អ្នកជិះសេះម្នាក់ចេញពី \(A\) ទៅដងទឹកត្រង់ \(M\) លើច្រាំងទន្លេ រួចបន្តទៅ \(B\)។ រកប្រវែងផ្លូវខ្លីបំផុត \(AM + MB\) និងកូអរដោនេនៃ \(M\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ឆ្លុះចំណុច A(1, 3) ធៀបនឹង Ox បានចំណុច A''(1, -3) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12447, 'PISA ការឆ្លុះរូបលើកញ្ចក់ស្ថាបត្យកម្ម: អាគារខ្ពស់មួយមានកម្ពស់ \(40\text{ m}\) ឈរនៅមាត់ស្រះទឹកថ្លា។ កំពូលអគារមានកូអរដោនេ \(T(15, 40)\) ធៀបនឹងផ្ទៃទឹក \(y = 0\)។ គណនាកូអរដោនេនៃរូបភាពឆ្លុះនៃកំពូលអគារក្នុងទឹក និងចម្ងាយរវាងកំពូលអគារពិតនិងរូបភាពឆ្លុះរបស់វា។', NULL, '[]', 0, NULL, 5, 'writing', 'ចាត់ទុកផ្ទៃទឹកជាអ័ក្សឆ្លុះ y = 0 (អ័ក្ស Ox) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12448, 'PISA អក្សរកាត់ស្លាកសញ្ញា: អ្នករចនាម៉ាកយីហោម្នាក់រចនាឡូហ្គោដោយឆ្លុះត្រីកោណ \(A(1, 1), B(3, 1), C(2, 4)\) ធៀបនឹងបន្ទាត់ \(y = x\)។ គណនាកូអរដោនេនៃកំពូលរូបភាពទាំងបី \(A\'', B\'', C\''\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្តឆ្លុះធៀបនឹងបន្ទាត់ y = x: (x, y) -> (y, x) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12449, 'PISA តុប៊ីយ៉ាឆ្លុះជញ្ជាំងពីរ: គ្រាប់ប៊ីយ៉ាត្រង់ \(P(2, 3)\) ត្រូវវាយឱ្យបុកជញ្ជាំងខាងក្រោម \(y = 0\) រួចផ្លាតទៅបុកជញ្ជាំងខាងស្តាំ \(x = 8\) ទើបចូលរន្ធត្រង់ \(R(6, 5)\)។ ពន្យល់វិធីសាស្ត្រគូសផ្លូវរត់នៃគ្រាប់ប៊ីយ៉ាដោយប្រើការបំប្លែងឆ្លុះ។', NULL, '[]', 0, NULL, 5, 'writing', 'ឆ្លុះចំណុចចាប់ផ្តើម P(2, 3) ធៀប y = 0 បាន P_1(2, -3) (1.5 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12450, 'PISA ស៊ីមេទ្រីស្លឹកឈើ និងសត្វល្អិត: ស្លាបមេអំបៅមួយមានភាពស៊ីមេទ្រីធៀបនឹងអ័ក្សដងខ្លួន \(x = 0\) (អ័ក្ស Oy)។ បើស្លាបស្តាំមានចុងស្លាបត្រង់ \((6, 4)\) និង \((8, 1)\) រកកូអរដោនេចុងស្លាបខាងឆ្វេង និងបញ្ជាក់ថាក្រឡាផ្ទៃស្លាបទាំងពីរប៉ុនគ្នា។', NULL, '[]', 0, NULL, 5, 'writing', 'អនុវត្តការបំប្លែងឆ្លុះធៀបនឹងអ័ក្ស Oy: (x, y) -> (-x, y) (1.5 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12501, 'រូបភាពនៃចំណុច \(M\) តាមការបំប្លែងវិលផ្ចិត \(A\) មុំ \(\alpha\) គឺចំណុច \(M\''\) ដែលផ្ទៀងផ្ទាត់លក្ខខណ្ឌណា?', NULL, '["\\(\\vec{AM} = \\vec{AM\\''}\\)", "\\(AM = AM\\''\\text{ និង } \\widehat{MAM\\''} = |\\alpha|\\)", "\\(AM\\'' = \\alpha \\cdot AM\\)", "\\(AM + AM\\'' = \\alpha\\)"]', 1, NULL, 1, 'mcq', 'តាមនិយមន័យ AM = AM'' និងមុំ MAM'' = |alpha|។', 'ការបំប្លែងវិល', 'easy', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12502, 'យោងតាមរូបខាងក្រោម រូបភាពនៃចំណុច \(P(x, y)\) តាមការបំប្លែងវិលផ្ចិត \(O(0, 0)\) មុំ \(90^\circ\) (ច្រាសទ្រនិច) គឺ៖', 'g10-98e8b9283a.svg', '["\\((-x,\\, -y)\\)", "\\((x,\\, -y)\\)", "\\((-y,\\, x)\\)", "\\((y,\\, -x)\\)"]', 2, NULL, 1, 'mcq', 'រូបមន្តបំប្លែងវិលផ្ចិត O មុំ 90^\circ គឺ (x, y) -> (-y, x)។', 'ការបំប្លែងវិល', 'easy', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12503, 'ការបំប្លែងវិលជុំវិញផ្ចិត \(O\) មុំ \(360^\circ\) ត្រូវគ្នានឹងការបំប្លែងណា?', NULL, '["ការបំប្លែងចាំង", "ការបំប្លែងកិល", "ការបំប្លែងឆ្លុះ", "ការបំប្លែងឯកលក្ខណៈ (Identity)"]', 3, NULL, 1, 'mcq', 'វិលមួយជុំពេញ 360^\circ ត្រឡប់មកទីតាំងដើមបេះបិទ r(P) = P។', 'ការបំប្លែងវិល', 'easy', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12504, 'យោងតាមរូបខាងក្រោម ចំណុច \(M\) វិលជុំវិញផ្ចិត \(A\) បានរូបភាព \(M\''\)។ តើមុំ \(\alpha\) ក្នុងរូបមានទិសដៅវិជ្ជមាន ឬអវិជ្ជមាន?', 'g10-07fa640446.svg', '["ទិសដៅស្របនឹងបន្ទាត់ដេក", "ទិសដៅវិជ្ជមាន (ច្រាសទ្រនិចនាឡិកា)", "ទិសដៅអវិជ្ជមាន (ស្របទ្រនិចនាឡិកា)", "គ្មានទិសដៅទេ"]', 1, NULL, 1, 'mcq', 'ទិសដៅច្រាសទ្រនិចនាឡិកា (Counterclockwise) គឺជាទិសដៅវិជ្ជមាន alpha > 0។', 'ការបំប្លែងវិល', 'easy', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12505, 'រូបភាពនៃចំណុច \(P(x, y)\) តាមការបំប្លែងវិលផ្ចិត \(O\) មុំ \(180^\circ\) គឺ៖', NULL, '["\\((y,\\, x)\\)", "\\((-y,\\, x)\\)", "\\((x,\\, -y)\\)", "\\((-x,\\, -y)\\)"]', 3, NULL, 1, 'mcq', 'វិល 180^\circ ដូរសញ្ញាទាំងពីរ (-x, -y) ដែលត្រូវនឹងការឆ្លុះធៀបនឹងគល់ O។', 'ការបំប្លែងវិល', 'easy', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12506, 'តើចំណុចណាជាចំណុចមិនប្រែប្រួល (Fixed point) នៃការបំប្លែងវិល \(r_{(O, \alpha)}\) ដែល \(\alpha \neq 0^\circ\)?', NULL, '["គ្មានចំណុចមិនប្រែប្រួលទេ", "គ្រប់ចំណុចទាំងអស់", "\\(\\text{ចំណុចផ្ចិតវិល } O\\)", "ចំណុច (1, 1)"]', 2, NULL, 1, 'mcq', 'ផ្ចិតវិល O មិនផ្លាស់ប្តូរទីតាំងទេ: r(O) = O។', 'ការបំប្លែងវិល', 'easy', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12507, 'រូបភាពនៃចំណុច \(P(x, y)\) តាមការបំប្លែងវិលផ្ចិត \(O\) មុំ \(-90^\circ\) (ស្របទ្រនិច) គឺ៖', NULL, '["\\((-y,\\, x)\\)", "\\((-x,\\, y)\\)", "\\((-y,\\, -x)\\)", "\\((y,\\, -x)\\)"]', 3, NULL, 1, 'mcq', 'វិល -90^\circ (ឬ 270^\circ) គឺ (y, -x)។', 'ការបំប្លែងវិល', 'easy', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12508, 'អង្កត់ \(AB\) មានប្រវែង \(6\text{ cm}\)។ តាមការបំប្លែងវិលជុំវិញចំណុចមួយ គេបានអង្កត់រូបភាព \(A\''B\''\) មានប្រវែង៖', NULL, '["\\(6\\sqrt{2}\\text{ cm}\\)", "\\(12\\text{ cm}\\)", "\\(6\\text{ cm}\\)", "\\(3\\text{ cm}\\)"]', 2, NULL, 1, 'mcq', 'ការបំប្លែងវិលរក្សាប្រវែងអង្កត់ដើម A''B'' = AB = 6 cm។', 'ការបំប្លែងវិល', 'easy', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12509, 'គេមានចំណុច \(A(4, 2)\)។ រករូបភាពនៃ \(A\) តាមការបំប្លែងវិលផ្ចិត \(O\) មុំ \(90^\circ\)៖', NULL, '["\\((2,\\, -4)\\)", "\\((-4,\\, -2)\\)", "\\((-2,\\, 4)\\)", "\\((4,\\, -2)\\)"]', 2, NULL, 1, 'mcq', 'A(4, 2) -> A''(-2, 4) តាមរូបមន្ត (-y, x)។', 'ការបំប្លែងវិល', 'easy', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12510, 'មុំមួយមានរង្វាស់ \(75^\circ\)។ តើរង្វាស់មុំរូបភាពតាមការបំប្លែងវិលស្មើប៉ុន្មាន?', NULL, '["\\(105^\\circ\\)", "\\(150^\\circ\\)", "\\(90^\\circ\\)", "\\(75^\\circ\\)"]', 3, NULL, 1, 'mcq', 'ការបំប្លែងវិលរក្សារង្វាស់មុំដដែល។', 'ការបំប្លែងវិល', 'easy', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12511, 'ការេ \(ABCD\) មានផ្ចិត \(O\)។ តើមុំវិលវិជ្ជមានតូចបំផុតណាជុំវិញ \(O\) ដែលបំប្លែងការេឱ្យត្រួតស៊ីលើខ្លួនឯង?', NULL, '["\\(45^\\circ\\)", "\\(180^\\circ\\)", "\\(60^\\circ\\)", "\\(90^\\circ\\)"]', 3, NULL, 2, 'mcq', 'ការេមាន 4 ជ្រុងស្មើគ្នា មុំតូចបំផុតគឺ 360^\circ / 4 = 90^\circ។', 'ការបំប្លែងវិល', 'medium', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12512, 'សមាសនៃការបំប្លែងវិលពីរជុំវិញផ្ចិត \(O\) រួម \(r_{(O, 45^\circ)} \circ r_{(O, 45^\circ)}\) ស្មើនឹង៖', NULL, '["\\(r_{(O, 0^\\circ)}\\)", "\\(r_{(O, 180^\\circ)}\\)", "\\(r_{(O, 45^\\circ)}\\)", "\\(r_{(O, 90^\\circ)}\\)"]', 3, NULL, 2, 'mcq', 'បូកមុំវិលបញ្ចូលគ្នា: 45^\circ + 45^\circ = 90^\circ។', 'ការបំប្លែងវិល', 'medium', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12513, 'ត្រីកោណ \(MNP\) មាន \(M(3, 1), N(5, 3), P(2, 6)\)។ តាមការបំប្លែងវិលផ្ចិត \(O\) មុំ \(90^\circ\) រកកូអរដោនេ \(M\''\) និង \(N\''\)៖', NULL, '["\\(M\\''(-3,\\, -1)\\text{ និង } N\\''(-5,\\, -3)\\)", "\\(M\\''(-1,\\, 3)\\text{ និង } N\\''(-3,\\, 5)\\)", "\\(M\\''(1,\\, -3)\\text{ និង } N\\''(3,\\, -5)\\)", "\\(M\\''(3,\\, -1)\\text{ និង } N\\''(5,\\, -3)\\)"]', 1, NULL, 2, 'mcq', 'M(3, 1) -> M''(-1, 3) និង N(5, 3) -> N''(-3, 5)។', 'ការបំប្លែងវិល', 'medium', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12514, 'ត្រីកោណសម័ង្ស \(ABC\) មានផ្ចិត \(O\)។ តើមុំវិលវិជ្ជមានតូចបំផុតណាជុំវិញ \(O\) ដែលបំប្លែងត្រីកោណឱ្យត្រួតស៊ីលើខ្លួនឯង?', NULL, '["\\(60^\\circ\\)", "\\(90^\\circ\\)", "\\(120^\\circ\\)", "\\(180^\\circ\\)"]', 2, NULL, 2, 'mcq', '360^\circ / 3 = 120^\circ។', 'ការបំប្លែងវិល', 'medium', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12515, 'ការបំប្លែងវិលច្រាសនៃ \(r_{(O, 60^\circ)}\) គឺ៖', NULL, '["\\(r_{(O, -60^\\circ)}\\)", "\\(r_{(O, 120^\\circ)}\\)", "\\(r_{(O, 30^\\circ)}\\)", "\\(S_O\\)"]', 0, NULL, 2, 'mcq', 'វិលត្រឡប់ក្រោយមុំ -60^\circ ជុំវិញផ្ចិត O។', 'ការបំប្លែងវិល', 'medium', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12516, 'ត្រីកោណ \(MNP\) មាន \(M(3, 1), N(5, 3), P(2, 6)\)។ តាមការបំប្លែងវិលផ្ចិត \(O\) មុំ \(-90^\circ\) រកកូអរដោនេ \(P\''\''\)៖', NULL, '["\\((2,\\, -6)\\)", "\\((-6,\\, 2)\\)", "\\((-2,\\, -6)\\)", "\\((6,\\, -2)\\)"]', 3, NULL, 2, 'mcq', '(x, y) -> (y, -x) នាំឱ្យ P(2, 6) -> (6, -2)។', 'ការបំប្លែងវិល', 'medium', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12517, 'ឆកោណទៀងទាត់មួយមានផ្ចិត \(O\)។ តើមុំវិលវិជ្ជមានតូចបំផុតណាជុំវិញ \(O\) ដែលបំប្លែងឆកោណឱ្យត្រួតស៊ីលើខ្លួនឯង?', NULL, '["\\(60^\\circ\\)", "\\(90^\\circ\\)", "\\(120^\\circ\\)", "\\(30^\\circ\\)"]', 0, NULL, 2, 'mcq', '360^\circ / 6 = 60^\circ។', 'ការបំប្លែងវិល', 'medium', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12518, 'បន្ទាត់ \(d: y = x\)។ តាមការបំប្លែងវិលផ្ចិត \(O\) មុំ \(90^\circ\) រកសមីការបន្ទាត់រូបភាព \(d\''\)៖', NULL, '["\\(y = 2x\\)", "\\(x = 0\\)", "\\(y = x\\)", "\\(y = -x\\)"]', 3, NULL, 2, 'mcq', 'មុំផ្អៀង 45^\circ + 90^\circ = 135^\circ => មេគុណ m'' = tan(135^\circ) = -1 => y = -x។', 'ការបំប្លែងវិល', 'medium', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12519, 'ត្រីកោណ \(ABC\) មួយមានក្រឡាផ្ទៃ \(15\text{ cm}^2\)។ តើក្រឡាផ្ទៃនៃត្រីកោណរូបភាពតាមការបំប្លែងវិលមុំ \(90^\circ\) ស្មើប៉ុន្មាន?', NULL, '["\\(30\\text{ cm}^2\\)", "\\(7.5\\text{ cm}^2\\)", "\\(15\\sqrt{2}\\text{ cm}^2\\)", "\\(15\\text{ cm}^2\\)"]', 3, NULL, 2, 'mcq', 'ការបំប្លែងវិលរក្សាក្រឡាផ្ទៃ S'' = S = 15 cm^2។', 'ការបំប្លែងវិល', 'medium', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12520, 'តើពហុកោណទៀងទាត់ដែលមាន \(n\) ជ្រុង មានមុំវិលតូចបំផុតណាដែលបំប្លែងវាឱ្យត្រួតស៊ីលើខ្លួនឯង?', NULL, '["\\(\\dfrac{360^\\circ}{n - 2}\\)", "\\(\\dfrac{180^\\circ}{n}\\)", "\\(\\dfrac{90^\\circ}{n}\\)", "\\(\\dfrac{360^\\circ}{n}\\)"]', 3, NULL, 2, 'mcq', 'ពហុកោណទៀងទាត់ n ជ្រុង មានស៊ីមេទ្រីវិលកម្រិត n ដូច្នេះមុំតូចបំផុតគឺ 360^\circ / n។', 'ការបំប្លែងវិល', 'medium', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12521, 'តើការបំប្លែងវិលមានលក្ខណៈដូចម្តេចចំពោះទិសដៅនៃរូប (Orientation)?', NULL, '["រក្សាទិសដៅនៃរូប (Preserves orientation)", "ប្តូរទំហំរូប", "ប្តូរទិសដៅនៃរូប", "គ្មានទំនាក់ទំនងនឹងទិសដៅ"]', 0, NULL, 2, 'mcq', 'ការបំប្លែងវិលជា Isometry ផ្ទាល់ (Direct isometry) វារក្សាទិសដៅនៃរូប។', 'ការបំប្លែងវិល', 'medium', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12522, 'រង្វង់ \((C): (x - 4)^2 + y^2 = 16\)។ តាមការបំប្លែងវិលផ្ចិត \(O\) មុំ \(90^\circ\) រកសមីការរង្វង់រូបភាព \((C\'')\)៖', NULL, '["\\(x^2 + (y + 4)^2 = 16\\)", "\\(x^2 + (y - 4)^2 = 16\\)", "\\((x + 4)^2 + y^2 = 16\\)", "\\((x - 4)^2 + (y - 4)^2 = 16\\)"]', 1, NULL, 2, 'mcq', 'ផ្ចិត I(4, 0) វិល 90^\circ បាន I''(0, 4) នាំឱ្យ x^2 + (y - 4)^2 = 16។', 'ការបំប្លែងវិល', 'medium', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12523, 'សមាសនៃការបំប្លែងវិលពីរជុំវិញផ្ចិតរួម \(O\) គឺ \(r_{(O, 120^\circ)} \circ r_{(O, 240^\circ)}\) ស្មើនឹង៖', NULL, '["\\(\\text{ការបំប្លែងឯកលក្ខណៈ } \\text{Id}\\)", "\\(r_{(O, 90^\\circ)}\\)", "\\(S_O\\)", "\\(r_{(O, 120^\\circ)}\\)"]', 0, NULL, 2, 'mcq', '120^\circ + 240^\circ = 360^\circ = 0^\circ ត្រូវគ្នានឹង Identity Id។', 'ការបំប្លែងវិល', 'medium', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12524, 'រូបភាពនៃចំណុច \(A(2, 0)\) តាមការបំប្លែងវិលផ្ចិត \(O\) មុំ \(60^\circ\) គឺ៖', NULL, '["\\((\\sqrt{3},\\, 1)\\)", "\\((1,\\, -\\sqrt{3})\\)", "\\((1,\\, \\sqrt{3})\\)", "\\((-1,\\, \\sqrt{3})\\)"]', 2, NULL, 2, 'mcq', 'x'' = r cos 60^\circ = 2 * (1/2) = 1, y'' = r sin 60^\circ = 2 * (\sqrt{3}/2) = \sqrt{3} នាំឱ្យ (1, \sqrt{3})។', 'ការបំប្លែងវិល', 'medium', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12525, 'គេមានចំណុច \(A(1, 2)\)។ រករូបភាពនៃចំណុច \(P(4, 2)\) តាមការបំប្លែងវិលផ្ចិត \(A\) មុំ \(90^\circ\)៖', NULL, '["\\((-2,\\, 4)\\)", "\\((4,\\, 5)\\)", "\\((1,\\, 5)\\)", "\\((1,\\, -1)\\)"]', 2, NULL, 3, 'mcq', 'AP = (3, 0)។ វិល 90^\circ បាន (-0, 3) = (0, 3) នាំឱ្យ P'' = A + (0, 3) = (1, 5)។', 'ការបំប្លែងវិល', 'hard', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12526, 'បន្ទាត់ \(d: 2x - y + 4 = 0\)។ រកសមីការបន្ទាត់រូបភាព \(d\''\) តាមការបំប្លែងវិលផ្ចិត \(O\) មុំ \(90^\circ\)៖', NULL, '["\\(x + 2y - 4 = 0\\)", "\\(x + 2y + 4 = 0\\)", "\\(x - 2y + 4 = 0\\)", "\\(2x + y + 4 = 0\\)"]', 1, NULL, 3, 'mcq', 'វិល 90^\circ: (x'', y'') = (-y, x) => x = y'', y = -x''។ ជំនួសចូល d: 2(y'') - (-x'') + 4 = x'' + 2y'' + 4 = 0។', 'ការបំប្លែងវិល', 'hard', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12527, 'ត្រីកោណ \(ABC\) មាន \(A(1, 1), B(4, 1), C(1, 5)\)។ តាមការបំប្លែងវិលផ្ចិត \(O\) មុំ \(90^\circ\) គេបាន \(A\''B\''C\''\)។ រកកូអរដោនេទីប្រជុំទម្ងន់ \(G\''\) នៃត្រីកោណរូបភាព៖', NULL, '["\\(\\left(-2,\\, \\dfrac{7}{3}\\right)\\)", "\\(\\left(-\\dfrac{7}{3},\\, 2\\right)\\)", "\\(\\left(-\\dfrac{7}{3},\\, -2\\right)\\)", "\\(\\left(2,\\, \\dfrac{7}{3}\\right)\\)"]', 1, NULL, 3, 'mcq', 'G = ((1+4+1)/3, (1+1+5)/3) = (2, 7/3)។ វិល 90^\circ បាន (-y, x) = (-7/3, 2)។', 'ការបំប្លែងវិល', 'hard', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12528, 'គេមានចំណុច \(A(2, 1)\)។ រករូបភាពនៃចំណុច \(P(2, 5)\) តាមការបំប្លែងវិលផ្ចិត \(A\) មុំ \(180^\circ\)៖', NULL, '["\\((2,\\, -3)\\)", "\\((2,\\, -5)\\)", "\\((-2,\\, 5)\\)", "\\((2,\\, 3)\\)"]', 0, NULL, 3, 'mcq', 'P'' = 2A - P = 2(2, 1) - (2, 5) = (4 - 2, 2 - 5) = (2, -3)។', 'ការបំប្លែងវិល', 'hard', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12529, 'បន្ទាត់ \(d: 3x + 4y - 12 = 0\)។ តាមការបំប្លែងវិលផ្ចិត \(O\) មុំ \(180^\circ\) រកសមីការបន្ទាត់រូបភាព \(d\''\)៖', NULL, '["\\(3x + 4y + 12 = 0\\)", "\\(3x + 4y - 12 = 0\\)", "\\(-3x + 4y - 12 = 0\\)", "\\(4x - 3y + 12 = 0\\)"]', 0, NULL, 3, 'mcq', 'ជំនួស x -> -x, y -> -y: 3(-x) + 4(-y) - 12 = 0 => -3x - 4y - 12 = 0 => 3x + 4y + 12 = 0។', 'ការបំប្លែងវិល', 'hard', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12530, 'ចតុកោណកែង \(ABCD\) មានផ្ចិត \(O\)។ តើការបំប្លែងវិលជុំវិញ \(O\) មុំណាដែលបំប្លែងចតុកោណកែងឱ្យត្រួតស៊ីលើខ្លួនឯង?', NULL, '["\\(45^\\circ\\)", "\\(90^\\circ\\)", "\\(180^\\circ\\)", "\\(60^\\circ\\)"]', 2, NULL, 3, 'mcq', 'ចតុកោណកែងមិនមែនការេមានស៊ីមេទ្រីវិលកម្រិត 2 ដូច្នេះមុំគឺ 360^\circ / 2 = 180^\circ។', 'ការបំប្លែងវិល', 'hard', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12531, 'ត្រីកោណ \(ABC\) វិលជុំវិញកំពូល \(A\) មុំ \(60^\circ\) បាន \(AB\''C\''\)។ តើត្រីកោណ \(ABB\''\) ជាត្រីកោណអ្វី?', NULL, '["ត្រីកោណសម័ង្ស", "ត្រីកោណសមបាតមានមុំ 120 ដឺក្រេ", "ត្រីកោណទ្រេត", "ត្រីកោណកែងសមបាត"]', 0, NULL, 3, 'mcq', 'AB = AB'' (លក្ខណៈវិល) និង ngle BAB'' = 60^\circ នាំឱ្យ ABB'' ជាត្រីកោណសម័ង្ស។', 'ការបំប្លែងវិល', 'hard', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12532, 'PISA កន្ត្រកវិល Ferris Wheel: កន្ត្រកវិលមួយមានកន្ត្រកអង្គុយចំនួន 12 ស្មើៗគ្នាជុំវិញរង្វង់។ តើមុំវិលរវាងកន្ត្រកពីរដែលនៅជាប់គ្នាស្មើប៉ុន្មាន?', NULL, '["\\(60^\\circ\\)", "\\(30^\\circ\\)", "\\(15^\\circ\\)", "\\(45^\\circ\\)"]', 1, NULL, 3, 'mcq', '360^\circ / 12 = 30^\circ។', 'ការបំប្លែងវិល', 'pisa', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12533, 'PISA ប្រព័ន្ធរ៉ាដាកងទ័ពជើងទឹក: ផ្ទាំងរ៉ាដាបង្វិលមួយជុំ (360 ដឺក្រេ) រៀងរាល់ 4 វិនាទីម្តង។ គណនាល្បឿនមុំវិលនៃរ៉ាដានេះជាដឺក្រេក្នុងមួយវិនាទី៖', NULL, '["\\(90^\\circ/\\text{s}\\)", "\\(180^\\circ/\\text{s}\\)", "\\(45^\\circ/\\text{s}\\)", "\\(36^\\circ/\\text{s}\\)"]', 0, NULL, 3, 'mcq', '360^\circ / 4 = 90^\circ/s។', 'ការបំប្លែងវិល', 'pisa', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12534, 'PISA ដៃយន្តការរ៉ូបូតឧស្សាហកម្ម: ដៃរ៉ូបូតមួយមានប្រវែង 50 cm វិលជុំវិញគល់ O ពីមុំ 0 ដឺក្រេ ទៅមុំ 90 ដឺក្រេ។ គណនាកូអរដោនេចុងដៃរ៉ូបូតនៅទីតាំងចុងក្រោយ បើទីតាំងដើមត្រង់ (50, 0)៖', NULL, '["\\((-50,\\, 0)\\)", "\\((0,\\, -50)\\)", "\\((0,\\, 50)\\)", "\\((50,\\, 50)\\)"]', 2, NULL, 3, 'mcq', '(50, 0) វិល 90^\circ បាន (-0, 50) = (0, 50)។', 'ការបំប្លែងវិល', 'pisa', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12535, 'PISA ទ្រនិចនាឡិកា: ក្នុងរយៈពេល 45 នាទី តើទ្រនិចនាទីវិលបានមុំប៉ុន្មានតាមទិសដៅស្របទ្រនិច?', NULL, '["\\(-90^\\circ\\)", "\\(-180^\\circ\\)", "\\(-360^\\circ\\)", "\\(-270^\\circ\\)"]', 3, NULL, 3, 'mcq', '45 នាទី = 3/4 ជុំ = 3/4 * 360^\circ = 270^\circ ស្របទ្រនិច គឺមុំ -270^\circ (ឬ 90^\circ ច្រាសទ្រនិច)។', 'ការបំប្លែងវិល', 'pisa', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12536, 'PISA ចង្កូតរថយន្ត: តៃកុងឡានម្នាក់បង្វិលចង្កូតរថយន្តរាងរង្វង់មុំ 90 ដឺក្រេ។ បើកាំនៃចង្កូតស្មើ 20 cm គណនាប្រវែងធ្នូដែលដៃរបស់គាត់បានរំកិល (យក \pi pprox 3.14)៖', NULL, '["\\(15.7\\text{ cm}\\)", "\\(31.4\\text{ cm}\\)", "\\(62.8\\text{ cm}\\)", "\\(10\\text{ cm}\\)"]', 1, NULL, 3, 'mcq', 'L = (90/360) * 2 * \pi * r = (1/4) * 2 * 3.14 * 20 = 31.4 cm។', 'ការបំប្លែងវិល', 'pisa', 1, '10', 'ការបំប្លែងវិល', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12537, 'គេមានចំណុច \(A(3, 5)\)។ គណនាកូអរដោនេនៃរូបភាព \(A\''\) តាមការបំប្លែងវិលផ្ចិត \(O\) មុំ \(90^\circ\) និងរូបភាព \(A\''\''\) តាមការបំប្លែងវិលផ្ចិត \(O\) មុំ \(180^\circ\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្តវិលផ្ចិត O មុំ 90^\circ: (x, y) -> (-y, x) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12538, 'ត្រីកោណ \(ABC\) មានកំពូល \(A(1, 1), B(4, 1), C(2, 4)\)។ រករូបភាពនៃត្រីកោណ \(A\''B\''C\''\) តាមការបំប្លែងវិលផ្ចិត \(O\) មុំ \(90^\circ\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្តវិលផ្ចិត O មុំ 90^\circ: (x, y) -> (-y, x) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12539, 'បន្ទាត់ \(d: x - 2y + 4 = 0\)។ រកសមីការបន្ទាត់រូបភាព \(d\''\) តាមការបំប្លែងវិលផ្ចិត \(O\) មុំ \(90^\circ\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរទំនាក់ទំនងប្តូរអថេរ: x'' = -y => y = -x'' និង y'' = x => x = y'' (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12540, 'ចូររៀបរាប់ពីលក្ខណៈស៊ីមេទ្រីវិល (Rotational symmetry) នៃការេមួយជុំវិញចំណុចប្រសព្វនៃអង្កត់ទ្រូងរបស់វា។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់ចំណុចប្រសព្វអង្កត់ទ្រូង O ជាផ្ចិតស៊ីមេទ្រីវិល (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12541, 'ត្រីកោណ \(PQR\) មានកំពូល \(P(2, 3), Q(5, 1), R(3, -2)\)។ រករូបភាពត្រីកោណ \(P\''Q\''R\''\) តាមការបំប្លែងវិលផ្ចិត \(O\) មុំ \(180^\circ\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្តវិលផ្ចិត O មុំ 180^\circ: (x, y) -> (-x, -y) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12542, 'គេមានចំណុច \(A(2, 3)\)។ រករូបភាពនៃចំណុច \(P(5, 7)\) តាមការបំប្លែងវិលផ្ចិត \(A\) មុំ \(90^\circ\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាវ៉ិចទ័រ AP = (5 - 2, 7 - 3) = (3, 4) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12543, 'រង្វង់ \((C): (x - 2)^2 + (y - 3)^2 = 9\)។ រកសមីការរង្វង់រូបភាព \((C\'')\) តាមការបំប្លែងវិលផ្ចិត \(O\) មុំ \(90^\circ\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់ផ្ចិត I(2, 3) និងកាំ R = 3 នៃរង្វង់ (C) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12544, 'ការេ \(ABCD\) មានកំពូល \(A(1, 0), B(3, 0), C(3, 2), D(1, 2)\)។ តាមការបំប្លែងវិលផ្ចិត \(O\) មុំ \(90^\circ\) រកកូអរដោនេនៃកំពូលទាំងបួននៃរូបភាព \(A\''B\''C\''D\''\)។', NULL, '[]', 0, NULL, 5, 'writing', 'អនុវត្តរូបមន្តវិល 90^\circ: (x, y) -> (-y, x) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12545, 'បង្ហាញថាសមាសនៃការបំប្លែងវិលពីរ \(r_{(O, \alpha)} \circ r_{(O, \beta)}\) គឺជាការបំប្លែងវិលជុំវិញផ្ចិត \(O\) មុំ \(\alpha + \beta\)។', NULL, '[]', 0, NULL, 5, 'writing', 'តាងចំណុច M(r cos 	heta, r sin 	heta) ក្នុងកូអរដោនេប៉ូលែ (1.5 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12546, 'PISA កន្ត្រកវិលទេសចរណ៍: កន្ត្រកវិលមួយមានកន្ត្រកអង្គុយចំនួន 8 ស្មើៗគ្នា និងមានកាំ \(R = 15\text{ m}\)។ កន្ត្រកមួយចេញដំណើរពីចំណុចទាបបំផុត \((0, -15)\) វិលបានមុំ \(135^\circ\) ច្រាសទ្រនិចនាឡិកា។ គណនាកម្ពស់នៃកន្ត្រកធៀបនឹងចំណុចផ្ចិតកណ្តាល។', NULL, '[]', 0, NULL, 5, 'writing', 'មុំផ្អៀងចាប់ផ្តើមពីទាបបំផុតគឺ -90^\circ (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12547, 'PISA ដៃយន្តការរ៉ូបូតកាត់ដែក: ដៃយន្តការមួយមានផ្ចិតវិលត្រង់ \(O(0, 0)\) និងចុងក្បាលកាត់ដែកត្រង់ \(P(30\text{ cm}, 40\text{ cm})\)។ ដៃយន្តការត្រូវវិលមុំ \(90^\circ\) ច្រាសទ្រនិចនាឡិកាដើម្បីកាត់ផ្ទាំងដែកមួយទៀត។ គណនាកូអរដោនេនៃទីតាំងថ្មី និងប្រវែងដៃរ៉ូបូត។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាប្រវែងដៃរ៉ូបូត L = OP = \sqrt{30^2 + 40^2} = 50\text{ cm} (1.5 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12548, 'PISA បង្វិលកាមេរ៉ាសុវត្ថិភាព: កាមេរ៉ាសុវត្ថិភាពមួយបំពាក់ត្រង់ចំណុច \(O(0, 0)\) អាចបង្វិលសង្កេតបានមុំ \(180^\circ\)។ នៅពេលបង្វិលពីទីតាំង \(A(20, -15)\) មុំ \(180^\circ\) រកកូអរដោនេគោលដៅ \(A\''\) និងចម្ងាយពី \(A\) ទៅ \(A\''\)។', NULL, '[]', 0, NULL, 5, 'writing', 'អនុវត្តរូបមន្តវិល 180^\circ: (x, y) -> (-x, -y) (1.5 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12549, 'PISA ចលនាទ្រនិចនាឡិកា: នាឡិកាមួយមានទ្រនិចម៉ោងប្រវែង 6 cm និងទ្រនិចនាទីប្រវែង 10 cm។ គណនាផលបូកចម្ងាយដែលចុងទ្រនិចទាំងពីរផ្លាស់ទីបានក្នុងរយៈពេល 3 ម៉ោងពេញ (យក \pi pprox 3.14)។', NULL, '[]', 0, NULL, 5, 'writing', 'ទ្រនិចម៉ោងវិលបាន 3 ម៉ោង = 3/12 ជុំ = 1/4 ជុំ: d_H = (1/4) * 2 * 3.14 * 6 = 9.42 cm (1.5 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12550, 'PISA កង្ហារខ្យល់ទួរប៊ីន: ស្លាបកង្ហារមួយមានស្លាប 3 ស្មើៗគ្នាប្រវែង 12 m ចេញពីផ្ចិតរួម O។ ស្លាបទីមួយចង្អុលទៅទិសខាងជើង (0, 12)។ គណនាកូអរដោនេនៃចុងស្លាបទីពីរ និងទីបី។', NULL, '[]', 0, NULL, 5, 'writing', 'មុំរវាងស្លាបនីមួយៗគឺ 360^\circ / 3 = 120^\circ (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12601, 'រូបភាពនៃចំណុច \(A\) តាមការបំប្លែងចាំងផ្ចិត \(P\) ផលធៀប \(c\) (\(c \neq 0\)) គឺចំណុច \(A\''\) ដែលផ្ទៀងផ្ទាត់ទំនាក់ទំនងណា?', NULL, '["\\(PA\\'' = c + PA\\)", "\\(\\vec{PA\\''} = c\\vec{PA}\\)", "\\(\\vec{AA\\''} = c\\vec{P}\\)", "\\(\\vec{PA} = c\\vec{PA\\''}\\)"]', 1, NULL, 1, 'mcq', 'តាមនិយមន័យ រូបភាព A'' កំណត់ដោយវ៉ិចទ័រ \vec{PA''} = c\vec{PA}។', 'ការបំប្លែងចាំង', 'easy', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12602, 'ក្នុងតម្រុយអរតូណរម៉ាល់ រូបភាពនៃចំណុច \(M(x, y)\) តាមការបំប្លែងចាំងផ្ចិត \(O(0, 0)\) ផលធៀប \(c\) គឺ៖', NULL, '["\\((x/c,\\, y/c)\\)", "\\((cx,\\, cy)\\)", "\\((x + c,\\, y + c)\\)", "\\((c/x,\\, c/y)\\)"]', 1, NULL, 1, 'mcq', 'រូបមន្តកូអរដោនេ: x'' = cx, y'' = cy នាំឱ្យ M''(cx, cy)។', 'ការបំប្លែងចាំង', 'easy', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12603, 'យោងតាមរូបខាងក្រោម បើ \(\vec{PA\''} = 3\vec{PA}\) នោះផលធៀបបំប្លែងចាំង \(c\) ស្មើប៉ុន្មាន?', 'g10-35c78af34f.svg', '["1/3", "3", "2", "6"]', 1, NULL, 1, 'mcq', 'ផលធៀបបំប្លែងចាំងគឺ c = 3។', 'ការបំប្លែងចាំង', 'easy', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12604, 'គេមានចំណុច \(A(2, -3)\)។ រករូបភាពនៃ \(A\) តាមការបំប្លែងចាំងផ្ចិត \(O\) ផលធៀប \(c = 3\)៖', NULL, '["\\((-6,\\, 9)\\)", "\\((6,\\, 9)\\)", "\\((5,\\, 0)\\)", "\\((6,\\, -9)\\)"]', 3, NULL, 1, 'mcq', 'A''(3 * 2, 3 * (-3)) = A''(6, -9)។', 'ការបំប្លែងចាំង', 'easy', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12605, 'បើផលធៀបបំប្លែងចាំង \(c > 0\) តើចំណុចរូបភាព \(A\''\) និងចំណុចដើម \(A\) ស្ថិតនៅទីតាំងណាធៀបនឹងផ្ចិត \(P\)?', NULL, '["កែងគ្នានឹង P", "នៅម្ខាងតែមួយនៃចំណុចផ្ចិត P", "នៅសងខាង (ម្ខាងម្នាក់) នៃចំណុចផ្ចិត P", "ត្រួតស៊ីគ្នាជានិច្ច"]', 1, NULL, 1, 'mcq', 'កាលណា c > 0 វ៉ិចទ័រ PA'' និង PA មានទិសដៅដូចគ្នា នាំឱ្យ A'' និង A នៅម្ខាងតែមួយនៃ P។', 'ការបំប្លែងចាំង', 'easy', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12606, 'គេមានចំណុច \(B(-4, 6)\)។ រករូបភាពនៃ \(B\) តាមការបំប្លែងចាំងផ្ចិត \(O\) ផលធៀប \(c = -\dfrac{1}{2}\)៖', NULL, '["\\((8,\\, -12)\\)", "\\((2,\\, -3)\\)", "\\((-2,\\, 3)\\)", "\\((-2,\\, -3)\\)"]', 1, NULL, 1, 'mcq', 'B''((-1/2)*(-4), (-1/2)*6) = B''(2, -3)។', 'ការបំប្លែងចាំង', 'easy', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12607, 'បើផលធៀបបំប្លែងចាំង \(c < 0\) តើចំណុចរូបភាព \(A\''\) និងចំណុចដើម \(A\) ស្ថិតនៅទីតាំងណាធៀបនឹងផ្ចិត \(P\)?', NULL, '["ត្រួតស៊ីលើ P", "នៅសងខាង (ម្ខាងម្នាក់) នៃចំណុចផ្ចិត P", "មិននៅលើបន្ទាត់តែមួយ", "នៅម្ខាងតែមួយនៃចំណុចផ្ចិត P"]', 1, NULL, 1, 'mcq', 'កាលណា c < 0 វ៉ិចទ័រ PA'' និង PA មានទិសដៅផ្ទុយគ្នា នាំឱ្យ A'' និង A នៅសងខាងនៃ P។', 'ការបំប្លែងចាំង', 'easy', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12608, 'យោងតាមរូបខាងក្រោម ត្រីកោណ \(A\''B\''C\''\) ជារូបភាពនៃ \(ABC\) តាមការបំប្លែងចាំងផ្ចិត \(O\) ផលធៀប \(c = 2\)។ បើ \(AB = 4\text{ cm}\) នោះ \(A\''B\''\) ស្មើ៖', 'g10-a8db0b9ad5.svg', '["\\(6\\text{ cm}\\)", "\\(16\\text{ cm}\\)", "\\(8\\text{ cm}\\)", "\\(2\\text{ cm}\\)"]', 2, NULL, 1, 'mcq', 'A''B'' = |c| AB = 2 * 4 = 8 cm។', 'ការបំប្លែងចាំង', 'easy', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12609, 'ការបំប្លែងចាំងផលធៀប \(c\) ជាការបង្រួមរូប (Reduction) លុះត្រាតែ៖', NULL, '["\\(c = 1\\)", "\\(c < 0\\)", "\\(|c| > 1\\)", "\\(0 < |c| < 1\\)"]', 3, NULL, 1, 'mcq', 'បើ 0 < |c| < 1 រូបភាពតូចជាងរូបដើម ដូច្នេះវាជាការបង្រួមរូប។', 'ការបំប្លែងចាំង', 'easy', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12610, 'អង្កត់ \(MN\) មានប្រវែង \(6\text{ cm}\)។ តាមការបំប្លែងចាំងផលធៀប \(c = -2\) រកប្រវែងអង្កត់រូបភាព \(M\''N\''\)៖', NULL, '["\\(8\\text{ cm}\\)", "\\(3\\text{ cm}\\)", "\\(-12\\text{ cm}\\)", "\\(12\\text{ cm}\\)"]', 3, NULL, 1, 'mcq', 'M''N'' = |-2| * 6 = 2 * 6 = 12 cm (ប្រវែងតែងតែវិជ្ជមាន)។', 'ការបំប្លែងចាំង', 'easy', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12611, 'តាមការបំប្លែងចាំងផ្ចិត \(O\) ចំណុច \(P(3, -4)\) មានរូបភាពជា \(P\''(-9, 12)\)។ រកផលធៀប \(c\)៖', NULL, '["\\(3\\)", "\\(-\\dfrac{1}{3}\\)", "\\(-3\\)", "\\(-4\\)"]', 2, NULL, 2, 'mcq', 'c = -9 / 3 = -3 (និង 12 / (-4) = -3)។', 'ការបំប្លែងចាំង', 'medium', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12612, 'ការបំប្លែងចាំងផ្ចិត \(P\) ផលធៀប \(c = -1\) ត្រូវគ្នានឹងការបំប្លែងណា?', NULL, '["ការបំប្លែងកិល", "ការបំប្លែងឆ្លុះធៀបនឹងចំណុច P (ឆ្លុះផ្ចិត)", "ការបំប្លែងឆ្លុះធៀបនឹងបន្ទាត់", "ការបំប្លែងវិល 90 ដឺក្រេ"]', 1, NULL, 2, 'mcq', 'PA'' = -PA នាំឱ្យ P ជាចំណុចកណ្តាលនៃ AA'' ត្រូវនឹងការឆ្លុះផ្ចិត P។', 'ការបំប្លែងចាំង', 'medium', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12613, 'ការបំប្លែងច្រាសនៃការបំប្លែងចាំង \(h_{(P, c)}\) គឺ៖', NULL, '["\\(h_{(P,\\, 1/c)}\\)", "\\(h_{(P,\\, c^2)}\\)", "\\(t_{-c}\\)", "\\(h_{(P,\\, -c)}\\)"]', 0, NULL, 2, 'mcq', 'ផលធៀបច្រាសគឺ 1/c ផ្ចិតដដែល P។', 'ការបំប្លែងចាំង', 'medium', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12614, 'ត្រីកោណ \(ABC\) មានក្រឡាផ្ទៃ \(16\text{ cm}^2\)។ តាមការបំប្លែងចាំងផលធៀប \(c = 3\) រកក្រឡាផ្ទៃនៃត្រីកោណរូបភាព \(A\''B\''C\''\)៖', NULL, '["\\(96\\text{ cm}^2\\)", "\\(48\\text{ cm}^2\\)", "\\(144\\text{ cm}^2\\)", "\\(256\\text{ cm}^2\\)"]', 2, NULL, 2, 'mcq', 'S'' = c^2 * S = 3^2 * 16 = 9 * 16 = 144 cm^2។', 'ការបំប្លែងចាំង', 'medium', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12615, 'ចំពោះ \(c \neq 1\) តើការបំប្លែងចាំងផ្ចិត \(P\) ផលធៀប \(c\) មានចំណុចមិនប្រែប្រួលប៉ុន្មាន?', NULL, '["មានរាប់មិនអស់", "គ្មានចំណុចមិនប្រែប្រួលទេ", "មានពីរចំណុច", "មានតែចំណុចផ្ចិត P មួយគត់"]', 3, NULL, 2, 'mcq', 'P ជាចំណុចតែមួយគត់ដែល h(P) = P។', 'ការបំប្លែងចាំង', 'medium', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12616, 'សមាសនៃការបំប្លែងចាំងពីរដែលមានផ្ចិតរួម \(P\) គឺ \(h_{(P, 2)} \circ h_{(P, 3)}\) ស្មើនឹង៖', NULL, '["\\(h_{(P,\\, 6)}\\)", "\\(t_6\\)", "\\(h_{(P,\\, 1)}\\)", "\\(h_{(P,\\, 5)}\\)"]', 0, NULL, 2, 'mcq', 'គុណផលធៀបទាំងពីរ: 2 * 3 = 6។', 'ការបំប្លែងចាំង', 'medium', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12617, 'ចតុកោណមួយមានក្រឡាផ្ទៃ \(40\text{ cm}^2\)។ តាមការបំប្លែងចាំងផលធៀប \(c = -\dfrac{1}{2}\) រកក្រឡាផ្ទៃនៃរូបភាព៖', NULL, '["\\(-20\\text{ cm}^2\\)", "\\(10\\text{ cm}^2\\)", "\\(-10\\text{ cm}^2\\)", "\\(20\\text{ cm}^2\\)"]', 1, NULL, 2, 'mcq', 'S'' = (-1/2)^2 * 40 = (1/4) * 40 = 10 cm^2។', 'ការបំប្លែងចាំង', 'medium', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12618, 'បន្ទាត់ \(d: 2x - y + 3 = 0\)។ រកសមីការបន្ទាត់រូបភាព \(d\''\) តាមការបំប្លែងចាំងផ្ចិត \(O\) ផលធៀប \(c = 2\)៖', NULL, '["\\(2x - y + 3 = 0\\)", "\\(2x - y + 6 = 0\\)", "\\(x - 2y + 6 = 0\\)", "\\(4x - 2y + 3 = 0\\)"]', 1, NULL, 2, 'mcq', 'ជំនួស x -> x/2, y -> y/2: 2(x/2) - (y/2) + 3 = 0 => x - y/2 + 3 = 0 => 2x - y + 6 = 0។', 'ការបំប្លែងចាំង', 'medium', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12619, 'រង្វង់ \((C): x^2 + y^2 = 9\)។ តាមការបំប្លែងចាំងផ្ចិត \(O\) ផលធៀប \(c = 2\) រកសមីការរង្វង់រូបភាព \((C\'')\)៖', NULL, '["\\(x^2 + y^2 = 18\\)", "\\(x^2 + y^2 = 36\\)", "\\(x^2 + y^2 = 12\\)", "\\(x^2 + y^2 = 81\\)"]', 1, NULL, 2, 'mcq', 'កាំដើម R = 3 => កាំថ្មី R'' = 2 * 3 = 6 នាំឱ្យ x^2 + y^2 = 6^2 = 36។', 'ការបំប្លែងចាំង', 'medium', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12620, 'តើការបំប្លែងចាំងរក្សាលក្ខណៈណាខាងក្រោមនេះ?', NULL, '["ភាពស្របគ្នានៃបន្ទាត់ (Parallelism)", "ចម្ងាយពីចំណុចមួយទៅចំណុចមួយ", "ប្រវែងអង្កត់", "ក្រឡាផ្ទៃ"]', 0, NULL, 2, 'mcq', 'ការបំប្លែងចាំងបំប្លែងបន្ទាត់ស្របទៅជាបន្ទាត់ស្រប និងបន្ទាត់មួយទៅជាបន្ទាត់ស្របនឹងវា។', 'ការបំប្លែងចាំង', 'medium', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12621, 'រង្វង់ \((C): (x - 2)^2 + (y - 4)^2 = 4\)។ តាមការបំប្លែងចាំងផ្ចិត \(O\) ផលធៀប \(c = \dfrac{1}{2}\) រកផ្ចិត \(I\''\) និងកាំ \(R\''\) នៃរូបភាព៖', NULL, '["\\(I\\''(2,\\, 4)\\text{ និង } R\\'' = 1\\)", "\\(I\\''(1,\\, 2)\\text{ និង } R\\'' = 2\\)", "\\(I\\''(4,\\, 8)\\text{ និង } R\\'' = 4\\)", "\\(I\\''(1,\\, 2)\\text{ និង } R\\'' = 1\\)"]', 3, NULL, 2, 'mcq', 'I'' = (1/2)*(2, 4) = (1, 2) និង R'' = (1/2)*2 = 1។', 'ការបំប្លែងចាំង', 'medium', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12622, 'បន្ទាត់ \(d: y = 3x\) កាត់តាមគល់ \(O\)។ តាមការបំប្លែងចាំងផ្ចិត \(O\) ផលធៀប \(c = 5\) តើសមីការបន្ទាត់រូបភាព \(d\''\) ជាអ្វី?', NULL, '["\\(y = \\dfrac{3}{5}x\\)", "\\(y = 3x + 5\\)", "\\(y = 3x\\text{ (ត្រួតស៊ីគ្នាលើ } d\\text{)}\\)", "\\(y = 15x\\)"]', 2, NULL, 2, 'mcq', 'បន្ទាត់កាត់តាមផ្ចិត O មិនផ្លាស់ប្តូរទីតាំងទេ d'' \equiv d។', 'ការបំប្លែងចាំង', 'medium', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12623, 'ត្រីកោណ \(ABC\) មាន \(A(1, 2), B(3, 4), C(5, 0)\)។ តាមការបំប្លែងចាំងផ្ចិត \(O\) ផលធៀប \(c = -2\) រកកូអរដោនេ \(B\''\)៖', NULL, '["\\((-1,\\, 2)\\)", "\\((-6,\\, -8)\\)", "\\((6,\\, 8)\\)", "\\((-6,\\, 8)\\)"]', 1, NULL, 2, 'mcq', 'B'' = -2 * (3, 4) = (-6, -8)។', 'ការបំប្លែងចាំង', 'medium', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12624, 'ត្រីកោណ \(ABC\) មានបរិមាត្រ \(18\text{ cm}\)។ តាមការបំប្លែងចាំងផលធៀប \(c = \dfrac{2}{3}\) រកបរិមាត្រនៃត្រីកោណរូបភាព៖', NULL, '["\\(12\\text{ cm}\\)", "\\(8\\text{ cm}\\)", "\\(27\\text{ cm}\\)", "\\(6\\text{ cm}\\)"]', 0, NULL, 2, 'mcq', 'P'' = |c| * P = (2/3) * 18 = 12 cm។', 'ការបំប្លែងចាំង', 'medium', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12625, 'គេមានចំណុច \(P(1, 2)\) និង \(A(4, 6)\)។ រករូបភាពនៃ \(A\) តាមការបំប្លែងចាំងផ្ចិត \(P\) ផលធៀប \(c = 2\)៖', NULL, '["\\((9,\\, 14)\\)", "\\((7,\\, 10)\\)", "\\((6,\\, 8)\\)", "\\((8,\\, 12)\\)"]', 1, NULL, 3, 'mcq', 'PA = (3, 4) => PA'' = 2*(3, 4) = (6, 8) => A'' = P + (6, 8) = (1+6, 2+8) = (7, 10)។', 'ការបំប្លែងចាំង', 'hard', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12626, 'គូបមួយមានមាឌ \(10\text{ cm}^3\)។ បើគេពង្រីកគូបនេះតាមផលធៀប \(c = 3\) តើមាឌនៃគូបថ្មីស្មើប៉ុន្មាន?', NULL, '["\\(270\\text{ cm}^3\\)", "\\(30\\text{ cm}^3\\)", "\\(90\\text{ cm}^3\\)", "\\(810\\text{ cm}^3\\)"]', 0, NULL, 3, 'mcq', 'មាឌគុណនឹង c^3: V'' = 3^3 * 10 = 27 * 10 = 270 cm^3។', 'ការបំប្លែងចាំង', 'hard', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12627, 'បន្ទាត់ \(d: 3x - 4y + 5 = 0\)។ រកចម្ងាយរវាងបន្ទាត់ \(d\) និងបន្ទាត់រូបភាព \(d\''\) តាមការបំប្លែងចាំងផ្ចិត \(O\) ផលធៀប \(c = 3\)៖', NULL, '["\\(10\\)", "\\(1\\)", "\\(3\\)", "\\(2\\)"]', 3, NULL, 3, 'mcq', 'd'': 3x - 4y + 15 = 0។ ចម្ងាយរវាងបន្ទាត់ស្របពីរ: |15 - 5| / \sqrt{3^2 + 4^2} = 10 / 5 = 2។', 'ការបំប្លែងចាំង', 'hard', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12628, 'គេមានចំណុច \(P(2, 3)\) និង \(A(5, 7)\)។ រករូបភាពនៃ \(A\) តាមការបំប្លែងចាំងផ្ចិត \(P\) ផលធៀប \(c = -1\)៖', NULL, '["\\((-5,\\, -7)\\)", "\\((-1,\\, -1)\\)", "\\((1,\\, 1)\\)", "\\((-1,\\, 1)\\)"]', 1, NULL, 3, 'mcq', 'PA = (3, 4) => PA'' = -1*(3, 4) = (-3, -4) => A'' = (2 - 3, 3 - 4) = (-1, -1)។', 'ការបំប្លែងចាំង', 'hard', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12629, 'ត្រីកោណ \(ABC\) មានទីប្រជុំទម្ងន់ \(G(3, 6)\)។ តាមការបំប្លែងចាំងផ្ចិត \(O\) ផលធៀប \(c = -\dfrac{1}{3}\) រកកូអរដោនេទីប្រជុំទម្ងន់ \(G\''\) នៃត្រីកោណរូបភាព៖', NULL, '["\\((-1,\\, -2)\\)", "\\((1,\\, 2)\\)", "\\((-1,\\, 2)\\)", "\\((-3,\\, -6)\\)"]', 0, NULL, 3, 'mcq', 'G'' = (-1/3) * (3, 6) = (-1, -2)។', 'ការបំប្លែងចាំង', 'hard', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12630, 'ប៉ារ៉ាបូល \((P): y = x^2\)។ រកសមីការប៉ារ៉ាបូលរូបភាព \((P\'')\) តាមការបំប្លែងចាំងផ្ចិត \(O\) ផលធៀប \(c = 2\)៖', NULL, '["\\(y = \\dfrac{1}{2}x^2\\)", "\\(y = 4x^2\\)", "\\(y = 2x^2\\)", "\\(y = \\dfrac{1}{4}x^2\\)"]', 0, NULL, 3, 'mcq', 'x'' = 2x => x = x''/2, y'' = 2y => y = y''/2។ ជំនួសចូល: y''/2 = (x''/2)^2 = x''^2/4 => y = (1/2)x^2។', 'ការបំប្លែងចាំង', 'hard', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12631, 'គេមានចំណុច \(P, A, B\) លើបន្ទាត់តែមួយដោយ \(\vec{PA} = 2\vec{i}\) និង \(\vec{PB} = 6\vec{i}\)។ ការបំប្លែងចាំងផ្ចិត \(P\) ដែលបំប្លែង \(A\) ទៅ \(B\) មានផលធៀបស្មើ៖', NULL, '["4", "2", "1/3", "3"]', 3, NULL, 3, 'mcq', 'c = PB / PA = 6 / 2 = 3។', 'ការបំប្លែងចាំង', 'hard', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12632, 'PISA ម៉ាស៊ីនបញ្ចាំងស្លាយ Projector: ស្លាយរូបថតមួយមានទំហំ 2 cm × 3 cm។ ម៉ាស៊ីនបញ្ចាំងពង្រីករូបភាពនេះលើអេក្រង់តាមផលធៀប c = 40។ គណនាក្រឡាផ្ទៃនៃរូបភាពលើអេក្រង់ជាម៉ែត្រការ៉េ (m^2)៖', NULL, '["\\(0.96\\text{ m}^2\\)", "\\(0.24\\text{ m}^2\\)", "\\(2.4\\text{ m}^2\\)", "\\(9.6\\text{ m}^2\\)"]', 0, NULL, 3, 'mcq', 'S_ដើម = 6 cm^2 = 0.0006 m^2 => S_អេក្រង់ = 40^2 * 6 cm^2 = 1600 * 6 = 9600 cm^2 = 0.96 m^2។', 'ការបំប្លែងចាំង', 'pisa', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12633, 'PISA កែវពង្រីកមីក្រូទស្សន៍: គ្រាប់បាក់តេរីមួយមានប្រវែងពិត 0.02 mm។ ក្រោមមីក្រូទស្សន៍ដែលពង្រីកតាមផលធៀប c = 500 តើគេមើលឃើញបាក់តេរីនោះមានប្រវែងប៉ុន្មានសង់ទីម៉ែត្រ (cm)?', NULL, '["\\(10\\text{ cm}\\)", "\\(5\\text{ cm}\\)", "\\(0.1\\text{ cm}\\)", "\\(1\\text{ cm}\\)"]', 3, NULL, 3, 'mcq', 'ប្រវែង = 500 * 0.02 mm = 10 mm = 1 cm។', 'ការបំប្លែងចាំង', 'pisa', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12634, 'PISA យន្តហោះគំរូខ្នាតតូច: យន្តហោះគំរូបង្រួមតាមមាត្រដ្ឋាន 1 : 50។ បើស្លាបយន្តហោះគំរូមានប្រវែង 80 cm តើស្លាបយន្តហោះពិតប្រាកដមានប្រវែងប៉ុន្មានម៉ែត្រ?', NULL, '["\\(50\\text{ m}\\)", "\\(4\\text{ m}\\)", "\\(40\\text{ m}\\)", "\\(400\\text{ m}\\)"]', 2, NULL, 3, 'mcq', 'ប្រវែងពិត = 80 cm * 50 = 4000 cm = 40 m។', 'ការបំប្លែងចាំង', 'pisa', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12635, 'PISA ស្រមោលបង្គោលផ្កាយ: ពិលមួយចាំងពន្លឺពីចំណុច O នៅចម្ងាយ 5 m ពីបង្គោលកម្ពស់ 3 m។ ស្រមោលបង្គោលធ្លាក់លើជញ្ជាំងដែលនៅចម្ងាយ 10 m ពីពិល។ គណនាកម្ពស់ស្រមោលលើជញ្ជាំង៖', NULL, '["\\(6\\text{ m}\\)", "\\(4.5\\text{ m}\\)", "\\(8\\text{ m}\\)", "\\(9\\text{ m}\\)"]', 0, NULL, 3, 'mcq', 'ផលធៀប c = 10 / 5 = 2 => h'' = 2 * 3 = 6 m។', 'ការបំប្លែងចាំង', 'pisa', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12636, 'PISA ប្លង់ស្ថាបត្យកម្មផ្ទះ: ប្លង់ផ្ទះមួយគូរតាមមាត្រដ្ឋាន 1 : 100 (c = 1/100)។ បន្ទប់ទទួលភ្ញៀវក្នុងប្លង់មានក្រឡាផ្ទៃ 30 cm^2។ គណនាក្រឡាផ្ទៃពិតជាក់ស្តែងជា m^2៖', NULL, '["\\(30\\text{ m}^2\\)", "\\(300\\text{ m}^2\\)", "\\(3\\text{ m}^2\\)", "\\(60\\text{ m}^2\\)"]', 0, NULL, 3, 'mcq', 'S_ពិត = 30 * 100^2 cm^2 = 300,000 cm^2 = 30 m^2 (ព្រោះ 1 m^2 = 10,000 cm^2)។', 'ការបំប្លែងចាំង', 'pisa', 1, '10', 'ការបំប្លែងចាំង', 'ជំពូកទី 9 : ការបំប្លែងរូបក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12637, 'គេមានចំណុច \(A(3, 4)\)។ គណនាកូអរដោនេនៃរូបភាព \(A\''\) តាមការបំប្លែងចាំងផ្ចិត \(O\) ផលធៀប \(c = 3\) និងរូបភាព \(A\''\''\) តាមផលធៀប \(c = -2\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្តកូអរដោនេបំប្លែងចាំងផ្ចិត O: (x, y) -> (cx, cy) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12638, 'ត្រីកោណ \(ABC\) មានកំពូល \(A(2, 4), B(6, 2), C(4, 6)\)។ រករូបភាពត្រីកោណ \(A\''B\''C\''\) តាមការបំប្លែងចាំងផ្ចិត \(O\) ផលធៀប \(c = \dfrac{1}{2}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្តបំប្លែងចាំង: (x, y) -> (x/2, y/2) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12639, 'បន្ទាត់ \(d: 4x - 3y + 12 = 0\)។ រកសមីការបន្ទាត់រូបភាព \(d\''\) តាមការបំប្លែងចាំងផ្ចិត \(O\) ផលធៀប \(c = 3\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្តប្តូរអថេរ: x'' = 3x => x = x''/3 និង y'' = 3y => y = y''/3 (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12640, 'ចូររៀបរាប់ពីលក្ខណៈគ្រឹះចំនួន ៤ នៃការបំប្លែងចាំងរូបធរណីមាត្រផលធៀប \(c\)។', NULL, '[]', 0, NULL, 5, 'writing', 'រក្សាភាពស្របគ្នានៃបន្ទាត់ (បន្ទាត់ស្របទៅជាបន្ទាត់ស្រប) (1.5 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12641, 'ត្រីកោណ \(ABC\) មួយមានក្រឡាផ្ទៃ \(24\text{ cm}^2\)។ គេបំប្លែងចាំងត្រីកោណនេះតាមផលធៀប \(c = 2\) ទៅជា \(A\''B\''C\''\)។ គណនាក្រឡាផ្ទៃនៃត្រីកោណរូបភាព \(A\''B\''C\''\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្តផលធៀបក្រឡាផ្ទៃ S'' / S = c^2 (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12642, 'គេមានចំណុច \(P(2, 1)\) និង \(A(4, 5)\)។ រករូបភាព \(A\''\) តាមការបំប្លែងចាំងផ្ចិត \(P\) ផលធៀប \(c = 3\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាវ៉ិចទ័រ PA = (4 - 2, 5 - 1) = (2, 4) (1.5 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12643, 'រង្វង់ \((C): (x - 2)^2 + (y + 1)^2 = 4\)។ រកសមីការរង្វង់រូបភាព \((C\'')\) តាមការបំប្លែងចាំងផ្ចិត \(O\) ផលធៀប \(c = 3\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់ផ្ចិត I(2, -1) និងកាំ R = 2 នៃរង្វង់ (C) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12644, 'ត្រីកោណ \(ABC\) មាន \(A(1, 1), B(4, 1), C(1, 5)\)។ តាមការបំប្លែងចាំងផ្ចិត \(O\) ផលធៀប \(c = -2\) គេបាន \(A\''B\''C\''\)។ គណនាក្រឡាផ្ទៃ និងប្រវែងបរិមាត្រនៃត្រីកោណរូបភាព។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាជ្រុងត្រីកោណកែង ABC: AB = 3, AC = 4, BC = 5 (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12645, 'គេមានចំណុច \(P(1, 3)\) និង \(A(5, -1)\)។ រករូបភាព \(A\''\) តាមការបំប្លែងចាំងផ្ចិត \(P\) ផលធៀប \(c = -2\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាវ៉ិចទ័រ PA = (5 - 1, -1 - 3) = (4, -4) (1.5 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12646, 'PISA ម៉ាស៊ីនបញ្ចាំងស្លាយលើជញ្ជាំង: ស្លាយរូបថតមួយមានទំហំ 24 mm × 36 mm។ នៅពេលបញ្ចាំងលើជញ្ជាំងសាលប្រជុំ រូបភាពមានកម្ពស់ 1.2 m (= 1200 mm) ត្រូវនឹងកម្ពស់ដើម 24 mm។ គណនាផលធៀបពង្រីក c និងទទឹងនៃរូបភាពលើជញ្ជាំង។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាផលធៀបពង្រីក c = 1200 / 24 = 50 (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12647, 'PISA ប្លង់គំនូរសាលារៀន: ប្លង់សាលារៀនមួយគូរតាមមាត្រដ្ឋាន 1 : 200 (c = 1/200)។ ទីលានបាល់ទាត់ក្នុងប្លង់មានទំហំ 5 cm × 3.5 cm។ គណនាទំហំពិតប្រាកដ (បណ្តោយ, ទទឹង) និងក្រឡាផ្ទៃពិតជាក់ស្តែងជាម៉ែត្រការ៉េ (m^2)។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាបណ្តោយពិត: 5 cm * 200 = 1000 cm = 10 m (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12648, 'PISA រូបថតឌីជីថលទូរស័ព្ទ: រូបថតមួយមានទំហំ 1000 ភីកសែល × 1500 ភីកសែល។ គេបង្រួមរូបនេះដើម្បីបង្ហោះតាមវេបសាយតាមផលធៀប c = 0.4។ គណនាទំហំភីកសែលថ្មីនៃរូបថត និងផលធៀបក្រឡាផ្ទៃរូបថតថ្មីធៀបនឹងរូបថតចាស់។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាវិមាត្រថ្មី: 1000 * 0.4 = 400 ភីកសែល និង 1500 * 0.4 = 600 ភីកសែល (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12649, 'PISA ការបញ្ចាំងពិលបង្កើតស្រមោល: ពិលមួយបញ្ចាំងពន្លឺពីចំណុច O នៅចម្ងាយ 3 m ពីបង្គោល AB ដែលមានកម្ពស់ 1.5 m។ ស្រមោល A''B'' នៃបង្គោលធ្លាក់លើជញ្ជាំងដែលនៅចម្ងាយ 9 m ពីពិល។ គណនាកម្ពស់នៃស្រមោល A''B''។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាផលធៀបបំប្លែងចាំង c = d'' / d = 9 / 3 = 3 (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12650, 'PISA អាងហែលទឹកគំរូនិងអាងពិត: វិស្វកររចនាអាងហែលទឹកគំរូមួយដែលមានមាឌ 0.5 m^3។ អាងហែលទឹកពិតប្រាកដត្រូវបានសាងសង់ដោយពង្រីកគ្រប់វិមាត្រទាំងអស់តាមផលធៀប c = 6។ គណនាមាឌនៃអាងហែលទឹកពិតជាម៉ែត្រគូប (m^3)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្តផលធៀបមាឌក្នុងលំហ V'' / V = c^3 (2 ពិន្ទុ)
